/** All translations for zizhitongjian ch.052 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "資治通鑑 第052卷", literal: "Zizhi Tongjian, Volume 52.", idiomatic: "Zizhi Tongjian, Volume 52." },
  { zh: "【漢紀四十四】　起閼逢閹茂，盡旃蒙作噩，凡十二年。", literal: "【Han Records 44】 From Yanfeng Yanmao through Zhanmeng Zuo'e—in all, twelve years.", idiomatic: "【Han Records 44】 From the first year of the Yanfeng cycle through the last year of the Zhanmeng cycle—twelve years in all." },
  { zh: "夏，四月，車師後部司馬率後王加特奴等，掩擊北匈奴於閶吾陸谷，大破之；", literal: "In summer, the fourth month, the Rear Department of Cheshi major led the rear king Jiatenu and the rest in a surprise attack on the Northern Xiongnu at Qiangwu Lugu and greatly defeated them;", idiomatic: "In summer, in the fourth month, the major of the Rear Department of Cheshi led the rear king Jiatenu and others in a surprise attack on the Northern Xiongnu at Qiangwu Lugu and routed them;" },
  { zh: "獲單于母。", literal: "they captured the Chanyu's mother.", idiomatic: "they captured the Chanyu's mother." },
  { zh: "五月，戊戌，詔以春夏連旱，赦天下。", literal: "In the fifth month, on the day wuxu, an edict, because spring and summer had drought in succession, pardoned the realm.", idiomatic: "In the fifth month, on wuxu day, an edict, because drought had continued through spring and summer, pardoned the realm." },
  { zh: "上親自露坐德陽殿東廂請雨。", literal: "The sovereign in person sat exposed in the east wing of Deyang Hall to request rain.", idiomatic: "The emperor in person sat in the open in the east wing of Deyang Hall to pray for rain." },
  { zh: "以尚書周舉才學優深，特加策問。", literal: "Because Master of Writing Zhou Ju's talent and learning were outstanding and deep, he was specially given a written examination.", idiomatic: "Because Master of Writing Zhou Ju's talent and learning were outstanding, he was specially questioned by imperial rescript." },
  { zh: "舉對曰：「臣聞陰陽閉隔，則二氣否塞。", literal: "Ju replied, saying, \"Your servant has heard that when yin and yang are shut off and separated, the two qi are blocked and obstructed.\"", idiomatic: "Ju replied, \"Your servant has heard that when yin and yang are shut off and separated, the two qi are blocked and obstructed.\"" },
  { zh: "陛下廢文帝、光武之法，而循亡秦奢移之欲，內積怨女，外有曠夫。", literal: "\"Your Majesty has abandoned the laws of Emperor Wen and Emperor Guangwu and instead follows the extravagant and shifting desires of the perished Qin—within, resentful women accumulate; without, husbandless men stand.\"", idiomatic: "\"Your Majesty has abandoned the laws of Emperor Wen and Emperor Guangwu and instead follows the extravagant, shifting desires of the fallen Qin—within the palace resentful women accumulate; without, husbandless men abound.\"" },
  { zh: "自枯旱以來，彌歷年歲，未聞陛下改過之效，徒勞至尊暴露風塵，誠無益也。", literal: "\"Since the withering drought began, years have piled up, yet your servant has not heard of Your Majesty's effect in reforming faults. In vain the utmost honored one is exposed to wind and dust—it truly has no benefit.\"", idiomatic: "\"Since the drought began, years have passed, yet we have not heard that Your Majesty's reforms have had effect. In vain the Son of Heaven is exposed to wind and dust—it truly does no good.\"" },
  { zh: "陛下但務其華，不尋其實，猶緣木希魚，卻行求前。", literal: "\"Your Majesty only pursues the ornamental and does not seek the substance—like climbing a tree hoping for fish, or walking backward to advance.\"", idiomatic: "\"Your Majesty pursues only ornament and does not seek substance—like climbing a tree hoping for fish, or walking backward to go forward.\"" },
  { zh: "誠宜推信革政，崇道變惑，出後宮不御之女，除太官重膳之費。", literal: "\"It is truly fitting to extend trust and reform government, honor the Way and transform delusion, release the women of the rear palace whom Your Majesty does not visit, and remove the Grand Steward's heavy banquet expenses.\"", idiomatic: "\"You should extend trust and reform government, honor the Way and set aside delusion, release the women of the rear palace you do not visit, and cut the Grand Steward's lavish banquet expenses.\"" },
  { zh: "《易‧傳》曰：『陽惑天不旋日。", literal: "\"The Commentary on the Changes says: 'When yang deludes Heaven, the sun does not turn in a day.'\"", idiomatic: "\"The Commentary on the Changes says: 'When yang deludes Heaven, the sun does not complete its course in a day.'\"" },
  { zh: "』惟陛下留神裁察！", literal: "\"Only may Your Majesty keep your spirit and judge and examine!\"", idiomatic: "\"May Your Majesty give this your careful attention!\"" },
  { zh: "」帝復召舉面問得失，舉對以「宜慎官人，去貪污，遠佞邪。", literal: "\" The emperor again summoned Ju for a face-to-face inquiry into gains and losses. Ju replied with \"One should be careful in appointing officials, remove the greedy and corrupt, and keep sycophants and villains at a distance.\"", idiomatic: "\" The emperor again summoned Ju to question him in person about what was right and wrong. Ju replied that \"one should be careful in appointing officials, remove the greedy and corrupt, and keep sycophants and villains at a distance.\"" },
  { zh: "」帝曰：「官貪污、佞邪者為誰乎？", literal: "\" The emperor said, \"Who are the officials who are greedy, corrupt, sycophantic, and villainous?\"", idiomatic: "\" The emperor said, \"Who are the greedy, corrupt, sycophantic officials?\"" },
  { zh: "」對曰：「臣從下州超備機密，不足以別群臣。", literal: "\" He replied, \"Your servant, promoted from a lower province to fill a confidential post, is not sufficient to distinguish among the host of ministers.\"", idiomatic: "\" He replied, \"Your servant was promoted from a lower province to a confidential post and is not fit to distinguish among the ministers.\"" },
  { zh: "然公卿大臣數有直言者，忠貞也；", literal: "\"Yet among the ducal ministers and great officials, those who often speak plainly are the loyal and upright;", idiomatic: "\"Yet among the ducal ministers, those who often speak plainly are loyal and upright;" },
  { zh: "阿諛苟容者，佞邪也。", literal: "those who fawn and flatter and are complaisant are sycophants and villains.\"", idiomatic: "those who fawn and flatter for easy acceptance are sycophants and villains.\"" },
  { zh: "太史令張衡亦上疏言：「前年京師地震土裂。", literal: "Grand Astrologer Zhang Heng also submitted a memorial, saying, \"The year before last the capital had an earthquake and the earth split.\"", idiomatic: "Grand Astrologer Zhang Heng also submitted a memorial, saying, \"The year before last the capital suffered an earthquake and the earth split.\"" },
  { zh: "裂者，威分；", literal: "\"Splitting means authority divided;", idiomatic: "\"Splitting means authority divided;" },
  { zh: "震者，民擾也。", literal: "shaking means the people disturbed.\"", idiomatic: "shaking means the people disturbed.\"" },
  { zh: "竊懼聖思厭倦，制不專己，恩不忍割，與眾共威。", literal: "\"Your servant secretly fears that the sage mind grows weary, that control is not kept solely in oneself, that favor cannot bear to be cut off, and that authority is shared with the multitude.\"", idiomatic: "\"I fear that the imperial mind grows weary, that control is not kept solely in your hands, that favor cannot bear to be withdrawn, and that authority is shared with others.\"" },
  { zh: "威不可分，德不可共。", literal: "\"Authority cannot be divided; virtue cannot be shared.\"", idiomatic: "\"Authority cannot be divided; virtue cannot be shared.\"" },
  { zh: "願陛下思惟所以稽古率舊，勿使刑德八柄不由天子，然後神望允塞，災消不至矣。", literal: "\"Your servant wishes Your Majesty to reflect on how to examine antiquity and lead by old ways, and not let the eight handles of punishment and virtue pass outside the Son of Heaven—then the spirits' regard will be fulfilled and blocked, and disasters will dissolve and not arrive.\"", idiomatic: "\"May Your Majesty reflect on how to examine antiquity and follow established ways, and not let the eight handles of punishment and virtue escape the Son of Heaven's grasp—then Heaven's regard will be satisfied and disasters will cease to come.\"" },
  { zh: "」衡又以中興之後，儒者爭學《圖緯》，上疏言：「《春秋元命包》有公輸班與墨翟，事見戰國；", literal: "\" Heng also, because after the restoration scholars vied to study Charts and Wefts, submitted a memorial, saying, \"The Yuanmingbao of the Spring and Autumn Annals has Gongshu Ban and Mozi—events seen in the Warring States period;\"", idiomatic: "\" Heng also submitted a memorial, because after the restoration scholars vied to study Charts and Wefts, saying, \"The Yuanmingbao of the Spring and Autumn Annals mentions Gongshu Ban and Mozi—events that belong to the Warring States period;\"" },
  { zh: "又言別有益州，益州之置在於漢世。", literal: "\"it also speaks separately of Yizhou, yet the establishment of Yizhou was in the Han age.\"", idiomatic: "\"it also speaks of a separate Yizhou, yet Yizhou was established in the Han dynasty.\"" },
  { zh: "又劉向父子領校秘書，閱定九流，亦無《讖錄》。", literal: "\"Again, Liu Xiang and his son, leading the collation of secret books and examining and fixing the nine schools, likewise had no Records of Omens.\"", idiomatic: "\"Again, Liu Xiang and his son, when they led the collation of the secret archives and fixed the nine schools, had no Records of Omens among them.\"" },
  { zh: "則知《圖讖》成於哀、平之際，皆虛偽之徒以要世取資，欺罔較然，莫之糾禁。", literal: "\"From this one knows that Charts and Omens were completed in the time of Ai and Ping—all were by false and deceitful men to beg the age and obtain resources. Their deception is comparatively plain, yet none corrects or forbids them.\"", idiomatic: "\"From this one knows that Charts and Omens were forged in the reigns of Ai and Ping—all the work of frauds seeking worldly gain. Their deception is plain, yet none corrects or forbids them.\"" },
  { zh: "且律歷、卦候、九宮、風角，數有征效，世莫肯學，而競稱不佔之書，譬猶畫工惡圖犬馬而好作鬼魅，誠以實事難形而虛偽不窮也！", literal: "\"Moreover, calendrical astronomy, hexagram prognostication, the nine palaces, and wind angles—several times have verified effects—yet the age will not study them, while all vie to praise books that make no prognostication. It is like a painter who hates drawing dogs and horses but loves painting ghosts and demons—truly because real things are hard to depict while falsehoods never end!\"", idiomatic: "\"Moreover calendrical astronomy, hexagram prognostication, the nine palaces, and wind angles have often proved effective, yet the age will not study them while all vie to praise books that make no prognostication. It is like a painter who hates drawing dogs and horses but loves painting ghosts and demons—truly because real things are hard to depict while falsehoods never end!\"" },
  { zh: "宜收藏《圖讖》，一禁絕之，則朱紫無所眩，典籍無瑕玷矣！", literal: "\"It is fitting to collect and store Charts and Omens and forbid them entirely—then crimson and purple will have nothing to dazzle, and the classics will have no stain!\"", idiomatic: "\"Charts and Omens should be collected and utterly forbidden—then falsehood will have nothing to dazzle the eye, and the classics will be without stain!\"" },
  { zh: "秋，七月，鐘羌良封等復寇隴西、漢陽。", literal: "In autumn, the seventh month, Zhong Qiang Liangfeng and the rest again raided Longxi and Hanyang.", idiomatic: "In autumn, in the seventh month, Zhong Qiang Liangfeng and others again raided Longxi and Hanyang." },
  { zh: "詔拜前校尉馬賢為謁者，鎮撫諸種。", literal: "An edict appointed the former colonel Ma Xian as Imperial Herald to pacify and comfort the various tribes.", idiomatic: "An edict appointed former Colonel Ma Xian Imperial Herald to pacify the various tribes." },
  { zh: "冬，十月，護羌校尉馬續遣兵擊良封，破之。", literal: "In winter, the tenth month, Protector of the Qiang Colonel Ma Xu dispatched troops to strike Liangfeng and defeated him.", idiomatic: "In winter, in the tenth month, Protector of the Qiang Colonel Ma Xu dispatched troops to strike Liangfeng and defeated him." },
  { zh: "十一月，壬寅，司徒劉崎、司空孔扶免，用國舉之言也。", literal: "In the eleventh month, on the day renyin, Minister of Education Liu Qi and Minister of Works Kong Fu were dismissed—because of Zhou Ju's words.", idiomatic: "In the eleventh month, on renyin day, Minister of Education Liu Qi and Minister of Works Kong Fu were dismissed—because of Zhou Ju's memorial." },
  { zh: "乙己，以大司農黃尚為司徒，光祿勳河東王卓為司空。", literal: "On the day yisi, Grand Minister of Agriculture Huang Shang was made Minister of Education, and Director of the Imperial Clan Wang Zhuo of Hedong was made Minister of Works.", idiomatic: "On yisi day Grand Minister of Agriculture Huang Shang was made Minister of Education, and Director of the Imperial Clan Wang Zhuo of Hedong was made Minister of Works." },
  { zh: "耿貴人數為耿氏請，帝乃紹封耿寶子箕為牟平侯。", literal: "The honored lady of the Geng clan repeatedly pleaded for the Geng family. The emperor thereupon continued the enfeoffment of Geng Bao's son Ji as Marquis of Mouping.", idiomatic: "The honored lady of the Geng clan repeatedly pleaded for the Geng family. The emperor thereupon restored the enfeoffment of Geng Bao's son Ji as Marquis of Mouping." },
  { zh: "春，北匈奴呼衍王侵車師後部。", literal: "In spring, the Northern Xiongnu Huyan king invaded the Rear Department of Cheshi.", idiomatic: "In spring the Northern Xiongnu Huyan king invaded the Rear Department of Cheshi." },
  { zh: "帝令敦煌太守發兵救之，不利。", literal: "The emperor ordered the Administrator of Dunhuang to dispatch troops to rescue them; it was not favorable.", idiomatic: "The emperor ordered the Administrator of Dunhuang to dispatch troops to rescue them; the effort failed." },
  { zh: "二月，丙子，初聽中官得以養子襲爵。", literal: "In the second month, on the day bingzi, for the first time palace attendants were permitted to adopt sons to inherit noble ranks.", idiomatic: "In the second month, on bingzi day, for the first time palace attendants were permitted to adopt sons to inherit noble ranks." },
  { zh: "初，帝之復位，宦官之力也，由是有寵，參與政事。", literal: "Earlier, the emperor's restoration had been through the eunuchs' strength; from this they had favor and participated in government affairs.", idiomatic: "Earlier the emperor's restoration had been the eunuchs' doing; from this they won favor and participated in government affairs." },
  { zh: "御史張綱上書曰：「竊尋文、明二帝，德化尤盛，中官常侍，不過兩人，近幸賞賜，裁滿數金，惜費重民，故家給人足。", literal: "Imperial Censor Zhang Gang submitted a memorial, saying, \"Your servant privately recalls that under Emperors Wen and Ming, virtue and transformation were especially abundant: palace attendant regular attendants were no more than two; favorites' rewards and gifts barely filled a few ounces of gold. They cherished expense and valued the people, and so households had enough and men were provided for.\"", idiomatic: "Imperial Censor Zhang Gang submitted a memorial, saying, \"I recall that under Emperors Wen and Ming virtue and transformation flourished: regular palace attendants numbered no more than two, and rewards to favorites barely amounted to a few ounces of gold. They cherished frugality and valued the people, and so households had enough and men were provided for.\"" },
  { zh: "而頃者以來，無功小人，皆有官爵，非愛民重器、承天順道者也。", literal: "\"Yet in recent times, worthless petty men all have offices and noble ranks—this is not loving the people, honoring the vessel of state, or receiving Heaven and following the Way.\"", idiomatic: "\"Yet in recent times worthless petty men all hold office and noble rank—this is not loving the people, honoring the vessel of state, or receiving Heaven and following the Way.\"" },
  { zh: "」書奏，不省。", literal: "\" The memorial was submitted; it was not heeded.", idiomatic: "\" The memorial was submitted; the emperor took no notice." },
  { zh: "綱，皓之子也。", literal: "Gang was the son of Hao.", idiomatic: "Gang was the son of Hao." },
  { zh: "旱。", literal: "Drought.", idiomatic: "Drought." },
  { zh: "謁者馬賢擊鐘羌，大破之。", literal: "Imperial Herald Ma Xian struck the Zhong Qiang and greatly defeated them.", idiomatic: "Imperial Herald Ma Xian struck the Zhong Qiang and routed them." },
  { zh: "夏，四月，甲子，太尉施延免。", literal: "In summer, the fourth month, on the day jiazi, Grand Commandant Shi Yan was dismissed.", idiomatic: "In summer, in the fourth month, on jiazi day Grand Commandant Shi Yan was dismissed." },
  { zh: "戊寅，以執金吾梁商為大將軍，故太尉寵參為太尉。", literal: "On the day wuyin, Bearer of the Gilded Mace Liang Shang was made Grand General; the former Grand Commandant Pang Can was made Grand Commandant.", idiomatic: "On wuyin day Bearer of the Gilded Mace Liang Shang was made Grand General; former Grand Commandant Pang Can was made Grand Commandant." },
  { zh: "商稱疾不起且一年，帝使太常桓焉奉策就第即拜，商乃詣闕受命。", literal: "Shang claimed illness and would not rise for nearly a year. The emperor sent Minister of Ceremonies Huan Yan with credentials to his residence for immediate investiture; Shang thereupon went to the gate and received the mandate.", idiomatic: "Shang claimed illness and would not take office for nearly a year. The emperor sent Minister of Ceremonies Huan Yan with credentials to his residence to invest him on the spot; Shang then came to court and accepted the mandate." },
  { zh: "商少通經傳，謙恭好士，辟漢陽巨覽、上黨陳龜為掾屬，李固為從事中郎，楊倫為長史。", literal: "Shang in youth had mastered the classics and commentaries, was modest and respectful and loved scholars. He recruited Ju Lan of Hanyang and Chen Gui of Shangdang as clerical subordinates, made Li Gu Attendant Gentleman, and Yang Lun Chief Clerk.", idiomatic: "Shang had mastered the classics in youth, was modest and loved scholars. He recruited Ju Lan of Hanyang and Chen Gui of Shangdang as clerks, made Li Gu Attendant Gentleman, and Yang Lun Chief Clerk." },
  { zh: "李固以商柔和自守，不能有所整裁，乃奏記於商曰：「數年以來，災怪屢見。", literal: "Li Gu, because Shang was gentle and mild and guarded himself, could not make any rectification or judgment. He thereupon submitted a note to Shang, saying, \"In recent years, disasters and prodigies have repeatedly appeared.\"", idiomatic: "Li Gu, seeing that Shang was gentle and self-protective and could not make bold reforms, submitted a note to Shang, saying, \"In recent years disasters and prodigies have repeatedly appeared.\"" },
  { zh: "孔子曰：『智者見變思形，愚者睹怪諱名。", literal: "\"Confucius said: 'The wise, seeing change, think of reshaping themselves; the foolish, seeing prodigies, hide their names.'\"", idiomatic: "\"Confucius said: 'The wise, seeing change, think how to reshape themselves; the foolish, seeing prodigies, hide their names.'\"" },
  { zh: "』天道無親，可為祗畏。", literal: "\"'Heaven's Way has no favorites—one may stand in reverent awe of it.\"", idiomatic: "\"'Heaven's Way shows no favoritism—one may stand in reverent awe of it.\"" },
  { zh: "誠令王綱一整，道行忠立，明公踵伯成之高，全不朽之譽，豈與此外戚凡輩耽榮好位者同日而論哉！", literal: "\"If truly the royal net were wholly ordered, the Way practiced and loyalty established, my lord would follow Bo Cheng's heights and preserve undying fame—how could you be spoken of in the same day as these vulgar affinal kin who cling to glory and love position!\"", idiomatic: "\"If the royal order were restored, the Way practiced and loyalty established, you would follow Bo Cheng's heights and preserve undying fame—how could you be spoken of in the same breath as these vulgar affinal kin who cling to glory and love office!\"" },
  { zh: "」商不能用。", literal: "\" Shang could not employ it.", idiomatic: "\" Shang did not act on it." },
  { zh: "秋，閏八月，丁亥朔，日有食之。", literal: "In autumn, in the intercalary eighth month, on the new moon of the day dinghai, the sun was eclipsed.", idiomatic: "In autumn, in the intercalary eighth month, on the new moon of dinghai day, there was a solar eclipse." },
  { zh: "冬，十月，烏桓寇雲中，度遼將軍耿曄追擊，不利。", literal: "In winter, the tenth month, the Wuhuan raided Yunzhong. General Who Crosses the Liao Geng Ye pursued and struck them; it was not favorable.", idiomatic: "In winter, in the tenth month, the Wuhuan raided Yunzhong. General Who Crosses the Liao Geng Ye pursued them; the effort failed." },
  { zh: "十一月，烏桓圍曄於蘭池城；", literal: "In the eleventh month, the Wuhuan besieged Ye at Lanchi city;", idiomatic: "In the eleventh month the Wuhuan besieged Ye at Lanchi city;" },
  { zh: "發兵數千人救之，烏桓乃退。", literal: "several thousand troops were dispatched to rescue him, and the Wuhuan thereupon withdrew.", idiomatic: "several thousand troops were dispatched to rescue him, and the Wuhuan withdrew." },
  { zh: "十二月，甲寅，京師地震。", literal: "In the twelfth month, on the day jiayin, the capital had an earthquake.", idiomatic: "In the twelfth month, on jiayin day, the capital suffered an earthquake." },
  { zh: "春，正月，己巳，改元，赦天下。", literal: "In spring, the first month, on the day jisi, the era name was changed and the realm pardoned.", idiomatic: "In spring, in the first month, on jisi day the era name was changed and the realm was pardoned." },
  { zh: "冬，十月，丁亥，承福殿火。", literal: "In winter, the tenth month, on the day dinghai, Chenfu Hall caught fire.", idiomatic: "In winter, in the tenth month, on dinghai day Chenfu Hall caught fire." },
  { zh: "十一月，丙子，太尉寵參罷。", literal: "In the eleventh month, on the day bingzi, Grand Commandant Pang Can was removed.", idiomatic: "In the eleventh month, on bingzi day Grand Commandant Pang Can was removed." },
  { zh: "十二月，像林蠻夷反。", literal: "In the twelfth month, the Xianglin barbarians rebelled.", idiomatic: "In the twelfth month the Xianglin barbarians rebelled." },
  { zh: "乙巳，以前司空王龔為太尉。", literal: "On the day yisi, the former Minister of Works Wang Gong was made Grand Commandant.", idiomatic: "On yisi day former Minister of Works Wang Gong was made Grand Commandant." },
  { zh: "龔疾宦官專權，上書極言其狀。", literal: "Gong hated that the eunuchs monopolized power and submitted a memorial stating their condition to the utmost.", idiomatic: "Gong hated eunuch monopoly of power and submitted a memorial describing it in full." },
  { zh: "諸黃門使客誣奏龔罪；", literal: "The various yellow gates' agents and clients falsely memorialized Gong's crimes;", idiomatic: "The various yellow gates' agents and clients falsely memorialized Gong's crimes;" },
  { zh: "上命龔亟自實。", literal: "the emperor ordered Gong urgently to confess the facts himself.", idiomatic: "the emperor ordered Gong urgently to confess the facts himself." },
  { zh: "李固奏記於梁商曰：「王公以堅貞之操，橫為讒佞所構，眾人聞知，莫不歎栗。", literal: "Li Gu submitted a note to Liang Shang, saying, \"Lord Wang, for his firm and upright conduct, has been set upon sideways by slanderers and villains. All who hear of it none fail to sigh and tremble.\"", idiomatic: "Li Gu submitted a note to Liang Shang, saying, \"Lord Wang, for his firm and upright conduct, has been set upon by slanderers and villains. All who hear of it sigh and tremble.\"" },
  { zh: "夫三公尊重，無詣理訴冤之義，纖微感概，輒引分決，是以舊典不有大罪，不至重問。", literal: "\"The Three Excellencies are honored and grave; they have no meaning of going to the law courts to plead injustice. At the slightest stirring of feeling they at once take leave and sever themselves—therefore the old statutes, unless there is great crime, do not reach heavy inquiry.\"", idiomatic: "\"The Three Excellencies are honored and grave; they do not go to law courts to plead injustice. At the slightest stirring of feeling they resign and sever themselves—therefore by old statute, unless the crime is grave, there is no heavy inquiry.\"" },
  { zh: "王公卒有它變，則朝廷獲害賢之名，群臣無救護之節矣！", literal: "\"If Lord Wang in the end has some other change, then the court will gain the name of harming the worthy, and the host of ministers will lack the integrity of rescue and protection!\"", idiomatic: "\"If Lord Wang comes to harm, the court will gain the name of harming the worthy, and the ministers will lack the integrity of rescue!\"" },
  { zh: "語曰：『善人在患，饑不及餐。", literal: "\"The saying goes: 'When a good man is in trouble, hunger does not wait for a meal.'\"", idiomatic: "\"The saying goes: 'When a good man is in trouble, hunger does not wait for a meal.'\"" },
  { zh: "』斯其時也！", literal: "\"'This is that time!\"", idiomatic: "\"'This is that time!\"" },
  { zh: "」商即言之於帝，事乃得釋。", literal: "\" Shang immediately spoke of it to the emperor, and the matter thereupon was released.", idiomatic: "\" Shang immediately spoke of it to the emperor, and the matter was dropped." },
  { zh: "是歲，以執金吾梁冀為河南尹。", literal: "That year, Bearer of the Gilded Mace Liang Ji was made Intendant of Henan.", idiomatic: "That year Bearer of the Gilded Mace Liang Ji was made Intendant of Henan." },
  { zh: "冀性嗜酒，逸游自恣，居職多縱暴非法。", literal: "Ji's nature loved wine; he wandered in pleasure and indulged himself. In office he often was unrestrained, violent, and unlawful.", idiomatic: "Ji loved wine, wandered in pleasure, and indulged himself. In office he was often unrestrained, violent, and unlawful." },
  { zh: "父商所親客雒陽令呂放以告商，商以讓冀。", literal: "His father Shang's intimate guest, Magistrate of Luoyang Lü Fang, reported this to Shang. Shang reproached Ji.", idiomatic: "His father Shang's intimate guest, Magistrate of Luoyang Lü Fang, reported this to Shang. Shang reproached Ji." },
  { zh: "冀遣人於道刺殺放，而恐商知之，乃推疑放之怨仇，請以放弟禹為雒陽令，使捕之；", literal: "Ji sent men on the road to assassinate Fang. Yet fearing Shang would know, he shifted suspicion onto Fang's enemies in resentment and requested that Fang's younger brother Yu be made Magistrate of Luoyang to have him arrested;", idiomatic: "Ji sent men on the road to assassinate Fang. Fearing Shang would learn of it, he shifted suspicion onto Fang's enemies and requested that Fang's younger brother Yu be made Magistrate of Luoyang to hunt them down;" },
  { zh: "盡滅其宗、親、賓客百餘人。", literal: "and utterly exterminated his clan, kin, and guests—more than a hundred persons.", idiomatic: "and utterly exterminated his clan, kin, and guests—more than a hundred persons." },
  { zh: "武陵太守上書，以蠻夷率服，可比漢人，增其租賦。", literal: "The Administrator of Wuling submitted a memorial that, because the barbarians had submitted in succession and could be compared to Han people, their land tax and levies should be increased.", idiomatic: "The Administrator of Wuling submitted a memorial that, because the barbarians had submitted and could be treated like Han subjects, their land tax and levies should be increased." },
  { zh: "議者皆以為可。", literal: "Those in council all thought it acceptable.", idiomatic: "Those in council all approved." },
  { zh: "尚書令虞詡曰：「自古聖王，不臣異俗。", literal: "Director of the Masters of Writing Yu Xu said, \"From antiquity the sage kings have not made alien customs into subjects.\"", idiomatic: "Director of the Masters of Writing Yu Xu said, \"From antiquity sage kings have not made alien peoples into subjects.\"" },
  { zh: "先帝舊典，貢稅多少，所由來久矣；", literal: "\"The former emperor's old statutes—how much tribute and tax, whence they came—have been long established;", idiomatic: "\"The former emperor's old statutes fixed how much tribute and tax was due—they have stood long;" },
  { zh: "今猥增之，必有怨叛。", literal: "\"now to rashly increase them will surely bring resentment and rebellion.\"", idiomatic: "\"to rashly increase them now will surely breed resentment and rebellion.\"" },
  { zh: "計其所得，不償所費，必有後悔。", literal: "\"Counting what will be obtained, it will not repay what is spent—there will surely be later regret.\"", idiomatic: "\"Count the gain against the cost and it will not repay the expense—there will surely be regret.\"" },
  { zh: "」帝不從。", literal: "\" The emperor did not follow.", idiomatic: "\" The emperor did not heed him." },
  { zh: "澧中、漊中蠻果爭貢布非舊約，遂殺鄉吏，舉種反。", literal: "The Lizhong and Laozhong barbarians indeed disputed tribute cloth as not matching the old agreement, thereupon killed village officials, and raised their tribes in rebellion.", idiomatic: "The Lizhong and Laozhong barbarians indeed disputed tribute cloth as exceeding the old agreement, killed village officials, and rose in rebellion tribe by tribe." },
  { zh: "春，武陵蠻二萬人圍充城，八千人寇夷道。", literal: "In spring, twenty thousand Wuling barbarians besieged Chong city; eight thousand raided Yidao.", idiomatic: "In spring twenty thousand Wuling barbarians besieged Chong city; eight thousand raided Yidao." },
  { zh: "二月，廣漢屬國都尉擊破白馬羌。", literal: "In the second month, the Commandery-Attached State Colonel of Guanghan defeated the White Horse Qiang.", idiomatic: "In the second month the Commandery-Attached State Colonel of Guanghan defeated the White Horse Qiang." },
  { zh: "帝遣武陵太守李進擊叛蠻，破平之。", literal: "The emperor dispatched the Administrator of Wuling Li Jin to strike the rebellious barbarians and defeated and pacified them.", idiomatic: "The emperor dispatched Administrator of Wuling Li Jin to strike the rebellious barbarians and defeated and pacified them." },
  { zh: "進乃簡選良吏，撫循蠻夷，郡境遂安。", literal: "Jin thereupon carefully selected good officials to comfort and lead the barbarians, and the commandery's territory was thereupon at peace.", idiomatic: "Jin then carefully selected good officials to comfort and lead the barbarians, and the commandery was pacified." },
  { zh: "三月，乙卯，司空王卓薨。", literal: "In the third month, on the day yimao, Minister of Works Wang Zhuo died.", idiomatic: "In the third month, on yimao day Minister of Works Wang Zhuo died." },
  { zh: "丁丑，以光祿勳郭虔為司空。", literal: "On the day dingchou, Director of the Imperial Clan Guo Qian was made Minister of Works.", idiomatic: "On dingchou day Director of the Imperial Clan Guo Qian was made Minister of Works." },
  { zh: "夏，四月，丙申，京師地震。", literal: "In summer, the fourth month, on the day bingshen, the capital had an earthquake.", idiomatic: "In summer, in the fourth month, on bingshen day the capital suffered an earthquake." },
  { zh: "五月，癸丑，山陽君宋娥坐構奸誣罔，收印綬，歸裡捨。", literal: "In the fifth month, on the day guichou, the Lord of Shanyang Song E, charged with framing wickedness and false deception, had her seal and cord taken and was returned to her village dwelling.", idiomatic: "In the fifth month, on guichou day the Lord of Shanyang Song E, charged with framing wickedness and false deception, had her seal and cord taken and was sent back to her village home." },
  { zh: "黃龍、楊佗、孟叔、李建、張賢、史泛、王道、李元、李剛等九侯坐與宋娥更相賂遺，求高官增邑，並遣就國，減租四分之一。", literal: "The nine marquises Huang Long, Yang Tuo, Meng Shu, Li Jian, Zhang Xian, Shi Fan, Wang Dao, Li Yuan, and Li Gang, charged with repeatedly bribing and sending gifts to one another with Song E to seek high office and increased fiefs, were all sent to their states and had their rents reduced by one quarter.", idiomatic: "The nine marquises Huang Long, Yang Tuo, Meng Shu, Li Jian, Zhang Xian, Shi Fan, Wang Dao, Li Yuan, and Li Gang, charged with repeatedly bribing Song E to seek high office and enlarged fiefs, were all sent to their states and had their rents reduced by one quarter." },
  { zh: "像林蠻區憐等攻縣寺，殺長吏。", literal: "The Xianglin barbarian Qu Lian and the rest attacked the county offices and killed the chief official.", idiomatic: "The Xianglin barbarian Qu Lian and others attacked the county offices and killed the chief official." },
  { zh: "交趾刺史樊演發交趾、九真兵萬餘人救之；", literal: "Inspector of Jiaozhi Fan Yan dispatched more than ten thousand troops from Jiaozhi and Jiuzhen to rescue them;", idiomatic: "Inspector of Jiaozhi Fan Yan dispatched more than ten thousand troops from Jiaozhi and Jiuzhen to rescue them;" },
  { zh: "兵士憚遠役，秋，七月，二郡兵反，攻其府。", literal: "the soldiers feared distant service. In autumn, the seventh month, the troops of the two commanderies rebelled and attacked his headquarters.", idiomatic: "the soldiers feared distant service. In autumn, in the seventh month, the troops of the two commanderies rebelled and attacked his headquarters." },
  { zh: "府雖擊破反者，而蠻勢轉盛。", literal: "Though the prefecture had struck down the rebels, the barbarian power turned and flourished.", idiomatic: "Though the prefecture had defeated the rebels, the barbarian forces grew stronger still." },
  { zh: "冬，十月，甲申，上行幸長安。", literal: "In winter, the tenth month, on the day jiashen, the emperor went on a progress to Chang'an.", idiomatic: "In winter, in the tenth month, on jiashen day the emperor went on a progress to Chang'an." },
  { zh: "扶風田弱薦同郡法真博通內外學，隱居不仕，宜就加袞職。", literal: "Tian Ruo of Fufeng recommended Fa Zhen of the same commandery, thoroughly versed in inner and outer learning, dwelling in seclusion and not serving office—he ought to be approached and granted an honored post.", idiomatic: "Tian Ruo of Fufeng recommended Fa Zhen of the same commandery, thoroughly versed in inner and outer learning, who lived in seclusion and would not take office, saying he ought to be approached and granted an honored post." },
  { zh: "帝虛心欲致之，前後四征，終不屈。", literal: "The emperor with open mind wished to summon him; before and after, four summonses—he ultimately would not yield.", idiomatic: "The emperor sincerely wished to summon him and summoned him four times, but he never yielded." },
  { zh: "友人郭正稱之曰：「法真名可得聞，身難得而見。", literal: "His friend Guo Zheng praised him, saying, \"Fa Zhen's name may be heard, but his person is hard to obtain and see.", idiomatic: "His friend Guo Zheng praised him, saying, \"Fa Zhen's name may be heard, but his person is hard to meet.\"" },
  { zh: "逃名而名我隨，避名而名我追，可謂百世之師者矣！", literal: "Fleeing name yet name follows me; shunning name yet name pursues me—he may be called a teacher for a hundred generations!\"", idiomatic: "\"He flees renown yet renown follows him; he shuns fame yet fame pursues him—he may be called a teacher for a hundred generations!\"" },
  { zh: "」真，雄之子也。", literal: "\" Zhen was Xiong's son.", idiomatic: "\" Zhen was the son of Fa Xiong." },
  { zh: "丁卯，京師地震。", literal: "On the day dingmao, the capital region was shaken by earthquake.", idiomatic: "On dingmao day the capital was shaken by an earthquake." },
  { zh: "太尉王龔以中常侍張昉等專弄國權，欲奏誅之。", literal: "Grand Commandant Wang Gong, because Palace Attendants Zhang Fang and the rest monopolized and manipulated state power, wished to memorialize and execute them.", idiomatic: "Grand Commandant Wang Gong, seeing that Palace Attendants Zhang Fang and others monopolized state power, wished to memorialize for their execution." },
  { zh: "宗親有以楊震行事諫之者，龔乃止。", literal: "Among the imperial clansmen there was one who admonished him citing Yang Zhen's conduct; Gong then stopped.", idiomatic: "A member of the imperial clan admonished him by citing Yang Zhen's example, and Gong desisted." },
  { zh: "十二月，乙亥，上還自長安。", literal: "In the twelfth month, on the day yihai, the emperor returned from Chang'an.", idiomatic: "In the twelfth month, on yihai day, the emperor returned from Chang'an." },
  { zh: "春，二月，乙亥，京師及金城、隴西地震，二郡山崩。", literal: "In spring, the second month, on the day yihai, the capital region and Jincheng and Longxi were shaken by earthquake; in the two commanderies mountains collapsed.", idiomatic: "In spring, in the second month, on yihai day, the capital and Jincheng and Longxi were shaken by earthquakes, and mountains collapsed in both commanderies." },
  { zh: "夏，閏四月，己酉，京師地震。", literal: "In summer, the intercalary fourth month, on the day jiyou, the capital region was shaken by earthquake.", idiomatic: "In summer, in the intercalary fourth month, on jiyou day, the capital was shaken by an earthquake." },
  { zh: "五月，吳郡丞羊珍反，攻郡府；", literal: "In the fifth month, Assistant Administrator of Wu commandery Yang Zhen rebelled and attacked the commandery headquarters;", idiomatic: "In the fifth month, Assistant Administrator of Wu commandery Yang Zhen rebelled and attacked the commandery headquarters;" },
  { zh: "太守王衡破斬之。", literal: "the Administrator Wang Heng defeated and beheaded him.", idiomatic: "Administrator Wang Heng defeated and beheaded him." },
  { zh: "侍御史賈昌與州郡並力討區憐等，不克，為所攻圍；", literal: "Attendant Censor Jia Chang, together with the provinces and commanderies with combined strength, campaigned against Ou Ling and the rest, could not overcome them, and was attacked and besieged by them;", idiomatic: "Attendant Censor Jia Chang, together with the provinces and commanderies, campaigned against Ou Ling and the rest but could not overcome them and was besieged;" },
  { zh: "歲餘，兵谷不繼。", literal: "more than a year passed, and troops and grain could not be sustained.", idiomatic: "After more than a year, troops and grain could not be sustained." },
  { zh: "帝召公卿百官及四府掾屬問以方略；", literal: "The emperor summoned the Three Excellencies, the hundred officials, and the clerks of the Four Bureaus to ask them for strategy;", idiomatic: "The emperor summoned the Three Excellencies, the hundred officials, and the clerks of the Four Bureaus to ask their counsel;" },
  { zh: "皆議遣大將，發荊、揚、兗、豫四萬人赴之。", literal: "all discussed sending a great general and raising forty thousand men from Jing, Yang, Yan, and Yu to go to their aid.", idiomatic: "all proposed sending a great general and raising forty thousand men from Jing, Yang, Yan, and Yu to go to their aid." },
  { zh: "李固駁曰：「若荊、揚無事，發之可也。", literal: "Li Gu rebutted, saying, \"If Jing and Yang were without trouble, sending them would be acceptable.", idiomatic: "Li Gu objected, saying, \"If Jing and Yang were untroubled, sending them would be acceptable.\"" },
  { zh: "今二州盜賊磐結不散，武陵、南郡蠻夷未輯，長沙、桂陽數被征發，如復擾動，必更生患，其不可一也。", literal: "Now in the two provinces bandits and robbers are coiled like rock and will not disperse; Wuling and Nan commandery barbarians are not yet pacified; Changsha and Guiyang have repeatedly been levied for campaigns—if again disturbed, trouble will surely arise anew. This is the first impossibility.", idiomatic: "\"But now in those two provinces bandits are entrenched and will not disperse; the barbarians of Wuling and Nan commandery are not yet pacified; and Changsha and Guiyang have repeatedly been levied for campaigns—if they are disturbed again, new troubles will surely arise. That is the first reason it will not do.\"" },
  { zh: "又，兗、豫之人卒被征發，遠赴萬里，無有還期，詔書迫促，必致叛亡，其不可二也。", literal: "Moreover, the people of Yan and Yu are suddenly levied for campaigns, sent far off ten thousand li with no date of return; the imperial edict presses urgently—they will surely flee in rebellion. This is the second impossibility.", idiomatic: "\"Moreover, the people of Yan and Yu would be suddenly levied and sent ten thousand li with no prospect of return; the edict would press them urgently and surely drive them to desert. That is the second reason.\"" },
  { zh: "南州水土溫暑，加有瘴氣，致死亡者十必四五，其不可三也。", literal: "The southern provinces' water and soil are warm and hot; added to this is miasma—of those who die, four or five in ten must perish. This is the third impossibility.", idiomatic: "\"The southern provinces are warm and humid, and miasma is added on top—four or five in ten will die. That is the third reason.\"" },
  { zh: "遠涉萬里，士卒疲勞，比至嶺南，不復堪鬥，其不可四也。", literal: "Traversing far ten thousand li, the soldiers and troops are weary and exhausted; by the time they reach Lingnan, they will no longer be fit to fight. This is the fourth impossibility.", idiomatic: "\"After marching ten thousand li the troops will be exhausted, and by the time they reach Lingnan they will no longer be fit to fight. That is the fourth reason.\"" },
  { zh: "軍行三十里為程，而去日南九千餘里，三百日乃到，計人稟五升，用米六十萬斛，不計將吏驢馬之食，但負甲自致，費便若此，其不可五也。", literal: "An army's march takes thirty li as one stage; yet to Rinan is more than nine thousand li—three hundred days are needed to arrive. Calculating each man's ration at five sheng, rice used would be six hundred thousand hu; not counting the food of generals, officials, donkeys, and horses—merely bearing armor and coming of themselves—the expense would be like this. This is the fifth impossibility.", idiomatic: "\"An army counts thirty li as one day's march, yet Rinan is more than nine thousand li away—three hundred days to arrive. At five sheng of grain per man, that would be six hundred thousand hu of rice, not counting food for officers, donkeys, and horses; merely to march there in armor would cost so much. That is the fifth reason.\"" },
  { zh: "設軍所在，死亡必眾，既不足禦敵，當復更發，此為刻割心腹以補四支，其不可六也。", literal: "Suppose the army is there—deaths will surely be many; already insufficient to repel the enemy, they must again be sent forth anew—this is carving and cutting the heart and belly to patch the four limbs. This is the sixth impossibility.", idiomatic: "\"Where the army is stationed deaths will be many; unable to repel the enemy, you would have to levy again—this would be carving out the heartland to patch the limbs. That is the sixth reason.\"" },
  { zh: "九真、日南相去千里，發其吏民猶尚不堪，何況乃苦四州之卒以赴萬里之艱哉！", literal: "Jiuzhen and Rinan are a thousand li apart; even levying their officials and people they still could not bear it—how much less to afflict the soldiers of four provinces to meet hardship ten thousand li away!", idiomatic: "\"Jiuzhen and Rinan are a thousand li apart; even levying their officials and people they could scarcely bear it—how much less to afflict the troops of four provinces with hardship ten thousand li away!\"" },
  { zh: "其不可七也。", literal: "This is the seventh impossibility.", idiomatic: "\"That is the seventh reason.\"" },
  { zh: "前中郎將尹就討益州叛羌，益州諺曰：『虜來尚可，尹來殺我。", literal: "Formerly Colonel of the Gentlemen of the Household Yin Jiu campaigned against the rebellious Qiang of Yizhou; a Yizhou proverb said, 'When the barbarians come it is still tolerable; when Yin comes he kills us.", idiomatic: "\"Formerly Colonel Yin Jiu campaigned against the rebellious Qiang of Yizhou, and a Yizhou proverb said, 'When the barbarians come it is still tolerable; when Yin comes he kills us.\"" },
  { zh: "』後就征還，以兵付刺史張喬；", literal: "' Later Yin was summoned back and handed the troops to Inspector Zhang Qiao;", idiomatic: "\"' Later Yin was recalled and handed the troops to Inspector Zhang Qiao;\"" },
  { zh: "喬因其將吏，旬月之間破殄寇虜。", literal: "Qiao, relying on his generals and officials, within ten days and a month utterly destroyed the bandit barbarians.", idiomatic: "Qiao, relying on his generals and officials, within a month or so utterly destroyed the bandits." },
  { zh: "此發將無益之效，州郡可任之驗也。", literal: "This is proof that sending generals yields no beneficial effect, while provinces and commanderies may be trusted.", idiomatic: "This shows that sending generals yields no benefit, while provinces and commanderies can be trusted." },
  { zh: "宜更選有勇略仁惠任將帥者，以為刺史、太守，悉使共住交趾。", literal: "It is fitting to select anew men of courage, strategy, benevolence, and grace fit to command armies and use them as inspectors and administrators, all sent to dwell together at Jiaozhi.", idiomatic: "You ought instead to select men of courage, strategy, benevolence, and grace fit to command armies and appoint them inspectors and administrators, all stationed together at Jiaozhi." },
  { zh: "今日南兵單無谷，守既不足，戰又不能，可一切徙其吏民，北依交趾，事靜之後，乃命歸本；", literal: "Now Rinan has few troops and no grain; to hold is already insufficient, to fight also impossible—all its officials and people may be moved wholesale north to rely on Jiaozhi; after affairs are quieted, then order them to return to their native places;", idiomatic: "\"Rinan now has few troops and no grain—unable to hold and unable to fight. Move all its officials and people north to Jiaozhi; after affairs are quieted, then order them home;\"" },
  { zh: "還募蠻夷使自相攻，轉輸金帛以為其資；", literal: "furthermore recruit the barbarians and have them attack one another, transporting gold and silks to supply them;", idiomatic: "\"recruit the barbarians to attack one another and transport gold and silks to supply them;\"" },
  { zh: "有能反間致頭首者，許以封侯裂土之賞。", literal: "whoever by counter-espionage can deliver the chiefs' heads—promise them enfeoffment as marquis and grants of carved territory as reward.", idiomatic: "\"whoever by counter-espionage can deliver the rebel chiefs, promise enfeoffment and grants of territory.\"" },
  { zh: "故并州刺史長沙祝良，性多勇決，又南陽張喬，前在益州有破虜之功，皆可任用。", literal: "Former Inspector of Bingzhou Zhu Liang of Changsha, by nature much given to courage and decisiveness, and also Zhang Qiao of Nanyang, who before in Yizhou had merit in destroying barbarians—both may be employed.", idiomatic: "\"Former Inspector of Bingzhou Zhu Liang of Changsha is by nature courageous and decisive, and Zhang Qiao of Nanyang, who before in Yizhou destroyed the barbarians, may both be employed.\"" },
  { zh: "昔太宗就加魏尚為雲中守，哀帝即拜龔捨為泰山守；", literal: "In the past Emperor Taizong on the spot added Wei Shang as Administrator of Yunzhong; Emperor Ai at once appointed Gong She as Administrator of Taishan;", idiomatic: "\"In the past Emperor Taizong on the spot appointed Wei Shang Administrator of Yunzhong, and Emperor Ai at once appointed Gong She Administrator of Taishan;\"" },
  { zh: "宜即拜良等，便道之官。", literal: "it is fitting at once to appoint Liang and the rest and send them by the direct road to their posts.", idiomatic: "\"appoint Liang and the rest at once and send them directly to their posts.\"" },
  { zh: "」四府悉從固議，即拜祝良為九真太守，張喬為交趾刺史。", literal: "\" The Four Bureaus all followed Gu's proposal; at once Zhu Liang was appointed Administrator of Jiuzhen and Zhang Qiao Inspector of Jiaozhi.", idiomatic: "\" The Four Bureaus all followed Gu's proposal and at once appointed Zhu Liang Administrator of Jiuzhen and Zhang Qiao Inspector of Jiaozhi." },
  { zh: "喬至，開示慰誘，並皆降散。", literal: "When Qiao arrived, he opened and explained, comforted and enticed them, and all alike submitted and dispersed.", idiomatic: "When Qiao arrived, he explained, comforted, and enticed them, and all submitted and dispersed." },
  { zh: "良到九真，單車入賊中，設方略，招以威信，降者數萬人，皆為良築起府寺。", literal: "When Liang reached Jiuzhen, in a single carriage he entered among the bandits, set out strategy, and summoned them with authority and trust; those who submitted numbered tens of thousands, and all built up headquarters and offices for Liang.", idiomatic: "When Liang reached Jiuzhen, he entered the bandit camp alone in a single carriage, laid out his strategy, and won them with authority and trust; tens of thousands submitted and all built headquarters for him." },
  { zh: "由是嶺外復平。", literal: "Thereby beyond the ranges was again pacified.", idiomatic: "Thereby the region beyond the ranges was pacified again." },
  { zh: "秋，八月，己未，司徒黃尚免。", literal: "In autumn, the eighth month, on the day jiwei, Minister over the Masses Huang Shang was dismissed.", idiomatic: "In autumn, in the eighth month, on jiwei day Minister over the Masses Huang Shang was dismissed." },
  { zh: "九月，己酉，以光祿勳長沙劉壽為司徒。", literal: "In the ninth month, on the day jiyou, Household Minister Liu Shou of Changsha was made Minister over the Masses.", idiomatic: "In the ninth month, on jiyou day Household Minister Liu Shou of Changsha was made Minister over the Masses." },
  { zh: "丙戌，令大將軍、三公舉剛毅、武猛、謀謨任將帥者各二人，特進、卿、校尉各一人。", literal: "On the day bingxu, the Grand General and the Three Excellencies were ordered each to recommend two men of firm resolve, martial fierceness, and strategic counsel fit to command armies; each Special Advancement, minister, and colonel one man.", idiomatic: "On bingxu day the emperor ordered the Grand General and the Three Excellencies each to recommend two men of firm resolve, martial fierceness, and strategic counsel fit to command armies, and each Special Advancement, minister, and colonel one man." },
  { zh: "初，尚書令左雄薦冀州刺史周舉為尚書。", literal: "Earlier, Master of Writing Zuo Xiong had recommended Inspector of Jizhou Zhou Ju as Master of Writing.", idiomatic: "Earlier Master of Writing Zuo Xiong had recommended Inspector of Jizhou Zhou Ju as Master of Writing." },
  { zh: "既而雄為司隸校尉，舉故冀州刺史馮直任將帥。", literal: "Afterward Xiong became Colonel of the Metropolitan Area; Ju recommended the former Inspector of Jizhou Feng Zhi as fit to command armies.", idiomatic: "Later Xiong became Colonel of the Metropolitan Area, and Ju recommended former Inspector of Jizhou Feng Zhi as fit to command armies." },
  { zh: "直嘗坐臧受罪，舉以此劾奏雄。", literal: "Zhi had once sat in guilt for corruption and received punishment; Ju on this ground impeached and memorialized against Xiong.", idiomatic: "Zhi had once been punished for corruption, and Ju on that ground impeached Xiong." },
  { zh: "雄曰：「詔書使我選武猛，不使我選清高。", literal: "Xiong said, \"The edict ordered me to select the martial and fierce, not to select the pure and lofty.", idiomatic: "Xiong said, \"The edict ordered me to select the martial and fierce, not the pure and lofty.\"" },
  { zh: "」舉曰：「詔書使君選武猛，不使君選貪污也。", literal: "\" Ju said, \"The edict ordered you, sir, to select the martial and fierce—it did not order you, sir, to select the corrupt.", idiomatic: "\" Ju said, \"The edict ordered you to select the martial and fierce—it did not order you to select the corrupt.\"" },
  { zh: "」雄曰：「進君，適所以自伐也。", literal: "\" Xiong said, \"Promoting you, sir, is precisely how I cut myself down.", idiomatic: "\" Xiong said, \"Promoting you, sir, is precisely how I cut myself down.\"" },
  { zh: "」舉曰：「昔趙宣子任韓厥為司馬，厥以軍法戮宣子僕，宣子謂諸大夫曰：『可賀我矣！", literal: "\" Ju said, \"In the past Zhao Xuanzi appointed Han Jue as Marshal; Jue by military law executed Xuanzi's servant. Xuanzi said to the great ministers, 'You may congratulate me!", idiomatic: "\" Ju said, \"In the past Zhao Xuanzi appointed Han Jue marshal; Jue by military law executed Xuanzi's servant. Xuanzi told the great ministers, 'You may congratulate me!\"" },
  { zh: "吾選厥也任其事。", literal: "I selected Jue, and he carried out his charge.", idiomatic: "\"'I selected Jue, and he carried out his charge.\"" },
  { zh: "』今君不以舉之不才誤升諸朝，不敢阿君以為君羞；", literal: "' Now you, sir, did not because of my lack of talent mistakenly elevate me to the court—I dare not fawn on you, sir, and thereby make shame for you, sir;", idiomatic: "\"'You, sir, did not because of my lack of talent mistakenly elevate me to court, and I dare not fawn on you and bring you shame;\"" },
  { zh: "不寤君之意與宣子殊也。", literal: "I did not awaken to that your intention, sir, differs from Xuanzi's.", idiomatic: "\"but I did not realize that your intention, sir, differs from Xuanzi's.\"" },
  { zh: "」雄悅，謝曰：「吾嘗事馮直之父，又與直善；", literal: "\" Xiong was pleased and apologized, saying, \"I once served Feng Zhi's father and was also on good terms with Zhi;", idiomatic: "\" Xiong was pleased and apologized, saying, \"I once served Feng Zhi's father and was also friendly with Zhi;\"" },
  { zh: "今宣光以此奏吾，是吾之過也！", literal: "now Xuan Guang memorializes me on this—it is my fault!", idiomatic: "\"now Xuan Guang has memorialized against me on this—it is my fault!\"" },
  { zh: "」天下益以此賢之。", literal: "\" All under Heaven the more on this account deemed them worthy.", idiomatic: "\" All under Heaven esteemed them the more for this." },
  { zh: "是時，宦官競賣恩勢，唯大長秋良賀清儉退厚。", literal: "At this time the eunuchs vied to sell favor and power; only the Grand Chamberlain for the Palace Liang He was pure, frugal, retiring, and generous.", idiomatic: "At this time the eunuchs vied to sell favor and power; only Grand Chamberlain for the Palace Liang He was pure, frugal, retiring, and generous." },
  { zh: "及詔舉武猛，賀獨無所薦。", literal: "When the edict ordered recommendations of martial fierceness, He alone recommended no one.", idiomatic: "When the edict ordered recommendations of martial fierceness, He alone recommended no one." },
  { zh: "帝問其故，對曰：「臣生自草茅，長於宮掖，既無知人之明，又未嘗交加士類。", literal: "The emperor asked the reason; he replied, \"Your servant was born from thatched huts and grew up in the palace women's quarters; I have neither the clarity to know men nor have I ever mingled with the scholar class.", idiomatic: "The emperor asked why; he replied, \"Your servant was born in humble circumstances and grew up in the palace quarters; I have neither the judgment to know men nor have I ever mingled with scholars.\"" },
  { zh: "昔衛鞅因景監以見，有識知其不終。", literal: "In the past Wei Yang gained audience through Jing Jian; those with insight knew he would not end well.", idiomatic: "\"In the past Wei Yang gained audience through Jing Jian, and those with insight knew he would not end well.\"" },
  { zh: "今得臣舉者，匪榮伊辱，是以不敢！", literal: "Now whoever gains recommendation through me—it is not glory but shame; therefore I dare not!\"", idiomatic: "\"Whoever would be recommended through me would gain not honor but shame; therefore I dare not!\"" },
  { zh: "」帝由是賞之。", literal: "\" The emperor on this account commended him.", idiomatic: "\" The emperor commended him for this." },
  { zh: "冬，十月，燒當羌那離等三千餘騎寇金城，校尉馬賢擊破之。", literal: "In winter, the tenth month, the Shaodang Qiang Nali and the rest, more than three thousand horsemen, raided Jincheng; Colonel Ma Xian struck and defeated them.", idiomatic: "In winter, in the tenth month, the Shaodang Qiang Nali and others, more than three thousand horsemen, raided Jincheng; Colonel Ma Xian defeated them." },
  { zh: "十二月，戊戌朔，日有食之。", literal: "In the twelfth month, on the new moon of the day wuxu, the sun was eclipsed.", idiomatic: "In the twelfth month, on the new moon of wuxu day, there was a solar eclipse." },
  { zh: "大將軍商以小黃門南陽曹節等用事於中，遣子冀、不疑與為交友；", literal: "Grand General Shang, because the Junior Palace Attendants Cao Jie of Nanyang and the rest held power within, sent his sons Ji and Buyi to befriend them;", idiomatic: "Grand General Shang, because Junior Palace Attendants Cao Jie of Nanyang and others held power within, sent his sons Ji and Buyi to befriend them;" },
  { zh: "而宦言忌其寵，反欲陷之。", literal: "yet the eunuchs' words resented their favor and instead wished to entrap them.", idiomatic: "but the eunuchs resented their favor and instead wished to entrap them." },
  { zh: "中常侍張逵、蘧政、楊定等與左右連謀，共譖商及中常侍曹騰、孟賁，云：「欲征諸王子，圖議廢立，請收商等案罪。", literal: "Palace Attendants Zhang Kui, Lu Zheng, Yang Ding, and the rest, together with the emperor's close attendants, conspired in league and jointly slandered Shang and Palace Attendants Cao Teng and Meng Ben, saying, \"They wish to summon the various princes and plot deliberation on deposal and installation—please arrest Shang and the rest and investigate their crimes.", idiomatic: "Palace Attendants Zhang Kui, Lu Zheng, Yang Ding, and others conspired with the emperor's close attendants and jointly slandered Shang and Palace Attendants Cao Teng and Meng Ben, saying, \"They wish to summon the various princes and plot deposal and installation—please arrest Shang and the rest and investigate their crimes.\"" },
  { zh: "」帝曰：「大將軍父子，我所親，騰、賁，我所愛，必無是，但汝曹共妒之耳。", literal: "\" The emperor said, \"The Grand General and his sons are those I am close to; Teng and Ben are those I love—surely there is nothing of this; it is only that you all jointly envy them.", idiomatic: "\" The emperor said, \"The Grand General and his sons are those I am close to; Teng and Ben are those I love—surely there is nothing of this; you are only jealous of them together.\"" },
  { zh: "」逵等知言不用，懼迫，遂出，矯詔收縛騰、賁於省中。", literal: "\" Kui and the rest knew their words were not used, feared being pressed, then went out and by forged edict arrested and bound Teng and Ben within the Secretariat.", idiomatic: "\" Kui and the rest, seeing their words were not heeded and fearing pressure, went out and by forged edict arrested and bound Teng and Ben within the Secretariat." },
  { zh: "帝聞，震怒，敕宦者李歙急呼騰、賁釋之；", literal: "The emperor heard of it, was shaken with anger, and ordered the eunuch Li Xin urgently to summon Teng and Ben and release them;", idiomatic: "The emperor heard of it, was furious, and ordered the eunuch Li Xin urgently to summon Teng and Ben and release them;" },
  { zh: "收逵等下獄。", literal: "Kui and the rest were arrested and imprisoned.", idiomatic: "Kui and the rest were arrested and imprisoned." },
  { zh: "春，正月，庚辰，逵等伏誅。", literal: "In spring, the first month, on the day gengchen, Kui and the rest were executed.", idiomatic: "In spring, in the first month, on gengchen day Kui and the rest were executed." },
  { zh: "事連弘農太守張鳳、安平相楊皓，皆坐死。", literal: "The affair implicated Administrator of Hongnong Zhang Feng and Chancellor of Anping Yang Hao; all sat in guilt and died.", idiomatic: "The affair implicated Administrator of Hongnong Zhang Feng and Chancellor of Anping Yang Hao; all were executed." },
  { zh: "辭所連染，延及在位大臣。", literal: "Confessions implicated and stained others, extending to great ministers in office.", idiomatic: "Confessions implicated others and extended to great ministers in office." },
  { zh: "商懼多侵枉，乃上疏曰：「《春秋》之義，功在元帥，罪止首惡。", literal: "Shang feared many would be wronged and invaded; he thereupon submitted a memorial, saying, \"The meaning of the Spring and Autumn Annals is: merit rests with the commander, guilt stops at the chief villain.", idiomatic: "Shang feared many would be wronged and submitted a memorial, saying, \"The meaning of the Spring and Autumn Annals is that merit rests with the commander and guilt stops at the chief villain.\"" },
  { zh: "大獄一起，無辜者眾，死囚久系，纖微成大，非所以順迎和氣，平政成化也。", literal: "When a great prison case arises, the innocent are many; condemned prisoners long detained—trifles become great. This is not the means to comply with and welcome harmonious qi, level government, and accomplish transformation.", idiomatic: "\"When a great prison case arises the innocent are many; condemned prisoners long detained turn trifles into grave matters—this is not how to welcome harmonious qi, level government, and accomplish transformation.\"" },
  { zh: "宜早訖章，以止逮捕之煩。", literal: "It is fitting early to conclude the case, to stop the trouble of arrests.", idiomatic: "\"You ought to conclude the case early and stop the trouble of arrests.\"" },
  { zh: "」帝納之，罪止坐者。", literal: "\" The emperor accepted it; guilt stopped at those who sat in it.", idiomatic: "\" The emperor accepted it; guilt stopped at those directly involved." },
  { zh: "二月，帝以商少子虎賁中郎將不疑為步兵校尉。", literal: "In the second month, the emperor made Shang's youngest son, Colonel of the Gentlemen of the Household of the Rapid Tigers Buyi, Colonel of the Footsoldiers.", idiomatic: "In the second month the emperor made Shang's youngest son, Colonel of the Rapid Tigers Buyi, Colonel of the Footsoldiers." },
  { zh: "商上書辭曰：「不疑童孺，猥處成人之位。", literal: "Shang submitted a memorial declining, saying, \"Buyi is a child; he has presumptuously been placed in a grown man's post.", idiomatic: "Shang submitted a memorial declining, saying, \"Buyi is a child and has presumptuously been placed in a grown man's post.\"" },
  { zh: "昔晏平仲辭鄁殿以守其富，公儀休不受魚飧以定其位。", literal: "In the past Yan Pingzhong declined the Ye palace to keep his wealth; Gongyi Xiu would not accept fish meals to fix his position.", idiomatic: "\"In the past Yan Ying declined the Ye palace to preserve his wealth, and Gongyi Xiu would not accept fish meals to secure his position.\"" },
  { zh: "臣雖不才，亦願固福祿於聖世！", literal: "Your servant, though without talent, also wishes to secure fortune and salary in this sage age!\"", idiomatic: "\"Your servant, though without talent, also wishes to secure fortune and salary in this sage age!\"" },
  { zh: "」上乃以不疑為侍中、奉車都尉。", literal: "\" The emperor thereupon made Buyi Palace Attendant and Commandant of the Imperial Carriages.", idiomatic: "\" The emperor thereupon made Buyi Palace Attendant and Commandant of the Imperial Carriages." },
  { zh: "三月，乙亥，京師地震。", literal: "In the third month, on the day yihai, the capital region was shaken by earthquake.", idiomatic: "In the third month, on yihai day, the capital was shaken by an earthquake." },
  { zh: "燒當羌那離等復反；", literal: "The Shaodang Qiang Nali and the rest again rebelled;", idiomatic: "The Shaodang Qiang Nali and others rebelled again;" },
  { zh: "夏，四月，癸卯，護羌校尉馬賢討斬之，獲首虜千二百餘級。", literal: "in summer, the fourth month, on the day guimao, Protector of the Qiang Colonel Ma Xian campaigned and beheaded them, obtaining more than twelve hundred heads and captives.", idiomatic: "in summer, in the fourth month, on guimao day Protector of the Qiang Colonel Ma Xian campaigned and beheaded them, taking more than twelve hundred heads and captives." },
  { zh: "戊午，赦天下。", literal: "On the day wuwu, all under Heaven was amnestied.", idiomatic: "On wuwu day all under Heaven was amnestied." },
  { zh: "五月，戊胡，封故濟北惠王壽子安為濟北王。", literal: "In the fifth month, on the day wuhu, the former Prince Hui of Jibei's son An was enfeoffed as King of Jibei.", idiomatic: "In the fifth month, on wuhu day the former Prince Hui of Jibei's son An was enfeoffed as King of Jibei." },
  { zh: "秋，八月，太原旱。", literal: "In autumn, the eighth month, Taiyuan suffered drought.", idiomatic: "In autumn, in the eighth month, Taiyuan suffered drought." },
  { zh: "春，二月，戊申，京師地震。", literal: "In spring, the second month, on the day wushen, the capital region was shaken by earthquake.", idiomatic: "In spring, in the second month, on wushen day, the capital was shaken by an earthquake." },
  { zh: "南匈奴句龍王吾斯、車紐等反，寇西河；", literal: "The Southern Xiongnu Gulong kings Wusi, Cheniu, and the rest rebelled and raided Xihe;", idiomatic: "The Southern Xiongnu Gulong kings Wusi, Che Niu, and others rebelled and raided Xihe;" },
  { zh: "招誘右賢王合兵圍美稷，殺朔方、代郡長吏。", literal: "they enticed and induced the Right Worthy King to combine forces and besiege Meiji, killing the chief officials of Shuofang and Dai commanderies.", idiomatic: "they induced the Right Worthy King to combine forces and besiege Meiji, killing the chief officials of Shuofang and Dai commanderies." },
  { zh: "夏，五月，度遼將軍馬續與中郎將梁並等發邊兵及羌、胡合二萬餘人掩擊，破之。", literal: "In summer, the fifth month, General Who Crosses the Liao Ma Xu, together with Colonel of the Gentlemen of the Household Liang Bing and the rest, raised border troops and Qiang and Hu combined, more than twenty thousand men, for a surprise attack and defeated them.", idiomatic: "In summer, in the fifth month, General Who Crosses the Liao Ma Xu, together with Colonel Liang Bing and others, raised more than twenty thousand border troops and Qiang and Hu for a surprise attack and defeated them." },
  { zh: "吾斯等復更屯聚，攻沒城邑。", literal: "Wusi and the rest again further gathered and encamped, attacking and overrunning cities and towns.", idiomatic: "Wusi and the rest gathered again, attacking and overrunning cities and towns." },
  { zh: "天子遣使責讓單于；", literal: "The Son of Heaven sent envoys to reproach and blame the chanyu;", idiomatic: "The emperor sent envoys to reproach the chanyu;" },
  { zh: "單于本不預謀，乃脫帽避帳，詣並謝罪。", literal: "the chanyu had originally not been party to the plot; he thereupon removed his cap and avoided the tent, went to Bing and apologized for his guilt.", idiomatic: "the chanyu had not been party to the plot; he removed his cap, left the tent, went to Bing, and apologized." },
  { zh: "並以病徵，五原太守陳龜代為中郎將。", literal: "Bing was summoned back on grounds of illness; Administrator of Wuyuan Chen Gui replaced him as Colonel of the Gentlemen of the Household.", idiomatic: "Bing was recalled on grounds of illness, and Administrator of Wuyuan Chen Gui replaced him as colonel." },
  { zh: "龜以單于不能制下，逼迫單于及其弟左賢王皆令自殺。", literal: "Gui, because the Chanyu could not control his subordinates, forced the Chanyu and his younger brother the Left Worthy King all to commit suicide.", idiomatic: "Chen Gui, because the Chanyu could not control his subordinates, forced the Chanyu and his younger brother the Left Worthy King all to commit suicide." },
  { zh: "龜又欲徙單于近親於內郡，而降者遂更狐疑。", literal: "Gui also wished to move the Chanyu's close kin into the interior commanderies, and those who had surrendered thus became doubly hesitant.", idiomatic: "Chen Gui also wished to move the Chanyu's close kin into the interior commanderies, and those who had surrendered thus became doubly hesitant." },
  { zh: "龜坐下獄，免。", literal: "Gui was convicted and imprisoned, then dismissed.", idiomatic: "Chen Gui was convicted and imprisoned, then dismissed." },
  { zh: "大將軍商上表曰：「匈奴寇畔，自知罪極。", literal: "Grand General-in-Chief Shang submitted a memorial, saying: \"The Xiongnu have raided and rebelled and know their guilt is extreme.", idiomatic: "Grand General-in-Chief Liang Shang submitted a memorial, saying, \"The Xiongnu have raided and rebelled and know their guilt is extreme." },
  { zh: "窮鳥困獸，皆知救死，況種類繁熾，不可單盡。", literal: "Birds at bay and beasts cornered all know to fight for their lives—how much more when their kind is numerous and flourishing and cannot be wiped out alone.", idiomatic: "Birds at bay and beasts cornered all know to fight for their lives—how much more when their kind is numerous and flourishing and cannot be wiped out alone." },
  { zh: "今轉運日增，三軍疲苦，虛內給外，非中國之利。", literal: "Now transport costs increase daily, the three armies are weary and distressed, draining the interior to supply the exterior—this is not to China's advantage.", idiomatic: "Now transport costs increase daily, the three armies are weary and distressed, draining the interior to supply the exterior—this is not to China's advantage." },
  { zh: "度遼將軍馬續，素有謀謨，且典邊日久，深曉兵要；", literal: "Crossing-the-Desert General Ma Xu has long had stratagems and plans, and having held the frontier for many years deeply understands military essentials;", idiomatic: "Crossing-the-Desert General Ma Xu has long had stratagems and plans, and having held the frontier for many years deeply understands military essentials;" },
  { zh: "每得續書，與臣策合。", literal: "Whenever I receive Xu's letters they accord with my plans.", idiomatic: "Whenever I receive Ma Xu's letters they accord with my plans." },
  { zh: "宜令續深溝高壁，以恩信招降，宣示購賞，明為期約。", literal: "He should be ordered to dig deep ditches and raise high walls, summon surrender with grace and trust, proclaim rewards for capture, and set clear deadlines.", idiomatic: "He should be ordered to dig deep ditches and raise high walls, summon surrender with grace and trust, proclaim rewards for capture, and set clear deadlines." },
  { zh: "如此，則丑類可服，國家無事矣。", literal: "Thus the hostile tribes can be subdued and the state will have no troubles.\"", idiomatic: "Thus the hostile tribes can be subdued and the state will have no troubles.\"" },
  { zh: "」帝從之，乃詔續招降畔虜。", literal: "\" The emperor followed this and thereupon ordered Xu to recruit surrender among rebel barbarians.", idiomatic: "\" The emperor followed this and thereupon ordered Ma Xu to recruit surrender among rebel barbarians." },
  { zh: "商又移書續等曰：「中國安寧，忘戰日久。", literal: "Shang again sent a letter to Xu and others, saying: \"China has been at peace and has forgotten warfare for a long time.", idiomatic: "Liang Shang again sent a letter to Ma Xu and others, saying, \"China has been at peace and has forgotten warfare for a long time." },
  { zh: "良騎野合，交鋒接矢，決勝當時，戎狄之所長而中國之所短也；", literal: "Good cavalry meeting in the open field, crossing blades and exchanging arrows, deciding victory on the spot—this is what the Rong and Di excel at and China lacks;", idiomatic: "Good cavalry meeting in the open field, crossing blades and exchanging arrows, deciding victory on the spot—this is what the Rong and Di excel at and China lacks;" },
  { zh: "強弩乘城，堅營固守，以待其衰，中國之所長而戎狄之所短也。", literal: "Powerful crossbows manning the walls, firm camps holding fast, waiting for their decline—this is what China excels at and the Rong and Di lack.", idiomatic: "Powerful crossbows manning the walls, firm camps holding fast, waiting for their decline—this is what China excels at and the Rong and Di lack." },
  { zh: "宜務先所長以觀其變，設購開賞，宣示反悔，勿貪小功以亂大謀。", literal: "One should stress first what one excels at and watch their changes, set rewards and open bounties, proclaim repentance, and not covet petty achievements to disrupt the great plan.", idiomatic: "One should stress first what one excels at and watch their changes, set rewards and open bounties, proclaim repentance, and not covet petty achievements to disrupt the great plan." },
  { zh: "」於是右賢王部抑鞮等萬三千口皆詣續降。", literal: "\" Thereupon more than thirteen thousand people including Yidi of the Right Worthy King's division all came to Xu and surrendered.", idiomatic: "\" Thereupon more than thirteen thousand people including Yidi of the Right Worthy King's division all came to Ma Xu and surrendered." },
  { zh: "己丑晦，日有食之。", literal: "On the last day of the month, jichou, there was a solar eclipse.", idiomatic: "On the last day of the month, jichou day, there was a solar eclipse." },
  { zh: "初，那離等既平，朝廷以來機為并州刺史，劉秉為涼州刺史。", literal: "Earlier, after Nali and others had been pacified, the court appointed Lai Ji as Inspector of Bing province and Liu Bing as Inspector of Liang province.", idiomatic: "Earlier, after Nali and others had been pacified, the court appointed Lai Ji as Inspector of Bing province and Liu Bing as Inspector of Liang province." },
  { zh: "機等天性虐刻，多所擾發；", literal: "Ji and the others were by nature cruel and harsh and frequently provoked disturbances;", idiomatic: "Lai Ji and the others were by nature cruel and harsh and frequently provoked disturbances;" },
  { zh: "且凍、傅難種羌遂反，攻金城，與雜種羌、胡大寇三輔，殺害長吏。", literal: "the Qiandong and Funan Qiang then rebelled, attacked Jincheng, and with miscellaneous Qiang and Hu greatly raided the Three Assistants, killing senior officials.", idiomatic: "the Qiandong and Funan Qiang then rebelled, attacked Jincheng, and with miscellaneous Qiang and Hu greatly raided the Three Assistants, killing senior officials." },
  { zh: "機、秉並坐征。", literal: "Ji and Bing were both summoned for punishment.", idiomatic: "Lai Ji and Liu Bing were both summoned to the capital for punishment." },
  { zh: "於是拜馬賢為征西將軍，以騎都尉耿叔為副，將左右羽林五校士及諸州郡兵十萬人屯漢陽。", literal: "Thereupon Ma Xian was appointed General Who Pacifies the West, with Cavalry Commandant Geng Shu as deputy, leading troops of the Left and Right Forest Guards, the Five Colonelcies, and commandery armies—one hundred thousand men—stationed at Hanyang.", idiomatic: "Thereupon Ma Xian was appointed General Who Pacifies the West, with Cavalry Commandant Geng Shu as deputy, leading troops of the Left and Right Forest Guards, the Five Colonelcies, and commandery armies—one hundred thousand men—stationed at Hanyang." },
  { zh: "九月，令扶風、漢陽築隴道塢三百所，置屯兵。", literal: "In the ninth month, Fufeng and Hanyang were ordered to build three hundred forts along the Long road and place garrison troops.", idiomatic: "In the ninth month, Fufeng and Hanyang were ordered to build three hundred forts along the Long road and place garrison troops." },
  { zh: "辛未，太尉王龔以老病罷。", literal: "On xinwei, Grand Commandant Wang Gong was dismissed for old age and illness.", idiomatic: "On xinwei day, Grand Commandant Wang Gong was dismissed for old age and illness." },
  { zh: "且凍羌寇武都，燒隴關。", literal: "The Qiandong Qiang raided Wudou and burned Long Pass.", idiomatic: "The Qiandong Qiang raided Wudou and burned Long Pass." },
  { zh: "壬午，以太常桓焉為太尉。", literal: "On renwu, Grand Master of Ceremonies Huan Yan was made Grand Commandant.", idiomatic: "On renwu day, Grand Master of Ceremonies Huan Yan was made Grand Commandant." },
  { zh: "匈奴句龍王吾斯等立車紐為單于，東引烏桓，西收羌、胡等數萬人攻破京兆虎牙營，殺上郡都尉及軍司馬，遂寇掠並、涼、幽、冀四州。", literal: "The Xiongnu Juguwang Wusi and others installed Che Niu as Chanyu, drew in the Wuhuan from the east and gathered Qiang, Hu, and others to the west—tens of thousands—broke through the Jingzhao Tiger-Tooth camp, killed the Commandant of Shang commandery and the army Major, and then raided and plundered the four provinces of Bing, Liang, You, and Ji.", idiomatic: "The Xiongnu Juguwang Wusi and others installed Che Niu as Chanyu, drew in the Wuhuan from the east and gathered Qiang, Hu, and others to the west—tens of thousands—broke through the Jingzhao Tiger-Tooth camp, killed the Commandant of Shang commandery and the army Major, and then raided and plundered the four provinces of Bing, Liang, You, and Ji." },
  { zh: "乃徙西河治離石，上郡治夏陽，朔方治五原。", literal: "The seat of Xihe was moved to Lishi, Shang commandery to Xiayang, and Shuofang to Wuyuan.", idiomatic: "The seat of Xihe was moved to Lishi, Shang commandery to Xiayang, and Shuofang to Wuyuan." },
  { zh: "十二月，遣使匈奴中郎將張耽將幽州、烏桓諸郡營兵擊車紐等，戰於馬邑，斬首三千級，獲生口甚眾。", literal: "In the twelfth month, the envoy and Xiongnu Colonel Zhang Dan was sent to lead the camp troops of You province, the Wuhuan, and various commanderies against Che Niu and others; they fought at Mayi, took three thousand heads, and captured a great many living captives.", idiomatic: "In the twelfth month, the envoy and Xiongnu Colonel Zhang Dan was sent to lead the camp troops of You province, the Wuhuan, and various commanderies against Che Niu and others. They fought at Mayi, took three thousand heads, and captured a great many living captives." },
  { zh: "車紐乞降，而吾斯猶率其部曲與烏桓寇鈔。", literal: "Che Niu begged to surrender, but Wusi still led his followers with the Wuhuan to raid.", idiomatic: "Che Niu begged to surrender, but Wusi still led his followers with the Wuhuan to raid." },
  { zh: "初，上命馬賢討西羌，大將軍商以為賢老，不如太中大夫宋漢；", literal: "Earlier, the emperor ordered Ma Xian to campaign against the Western Qiang; Grand General-in-Chief Shang thought Xian was old and that Grandee Counselor Song Han would be better;", idiomatic: "Earlier, the emperor ordered Ma Xian to campaign against the Western Qiang. Grand General-in-Chief Liang Shang thought Xian was old and that Grandee Counselor Song Han would be better;" },
  { zh: "帝不從。", literal: "the emperor did not follow this.", idiomatic: "The emperor did not follow this." },
  { zh: "漢，由之子也。", literal: "Han was the son of You.", idiomatic: "Song Han was the son of Song You." },
  { zh: "賢到軍，稽留不進。", literal: "Xian reached the army but lingered and did not advance.", idiomatic: "Ma Xian reached the army but lingered and did not advance." },
  { zh: "武都太守馬融上疏曰：「今雜種諸羌轉相鈔盜，宜及其未並，亟遣深入，破其支黨；", literal: "Administrator of Wudou Ma Rong submitted a memorial, saying: \"Now the various Qiang tribes are repeatedly robbing one another; while they have not yet united, troops should be sent quickly deep into their territory to break their branches and factions;", idiomatic: "Administrator of Wudou Ma Rong submitted a memorial, saying, \"Now the various Qiang tribes are repeatedly robbing one another. While they have not yet united, troops should be sent quickly deep into their territory to break their branches and factions;" },
  { zh: "而馬賢等處處留滯。", literal: "yet Ma Xian and others are stalled everywhere.", idiomatic: "yet Ma Xian and others are stalled everywhere." },
  { zh: "羌、胡百里望塵，千里聽聲，今逃匿避回，漏出其後，則必侵寇三輔，為民大害。", literal: "The Qiang and Hu see dust at a hundred li and hear at a thousand li; if they now hide and avoid us and slip out behind our backs, they will surely invade the Three Assistants—a great harm to the people.", idiomatic: "The Qiang and Hu see dust at a hundred li and hear at a thousand li. If they now hide and avoid us and slip out behind our backs, they will surely invade the Three Assistants—a great harm to the people." },
  { zh: "臣願請賢所不可，用關東兵五千，裁假部隊之號，盡力率厲，埋根、行首以先吏士；", literal: "Your servant wishes to request what Xian cannot do: use five thousand troops from east of the Pass, with only a borrowed troop designation, exert all strength to lead and encourage them, bury roots and take the vanguard ahead of the officials and soldiers;", idiomatic: "Your servant wishes to request what Ma Xian cannot do: use five thousand troops from east of the Pass, with only a borrowed troop designation, exert all strength to lead and encourage them, take the vanguard and go ahead of the officials and soldiers;" },
  { zh: "三旬之中，必克破之。", literal: "within thirty days they will surely be defeated and broken.", idiomatic: "within thirty days they will surely be defeated and broken." },
  { zh: "臣又聞吳起為將，暑不張蓋，寒不披裘；", literal: "Your servant also heard that when Wu Qi was general he did not raise an awning in summer or wear fur in winter;", idiomatic: "Your servant also heard that when Wu Qi was general he did not raise an awning in summer or wear fur in winter;" },
  { zh: "今賢野次垂幕，珍餚雜遝，兒子侍妾，事與古反。", literal: "now Xian in the field pitches curtains, rare delicacies are piled in confusion, sons and concubines attend him—conduct opposite to antiquity.", idiomatic: "now Ma Xian in the field pitches curtains, rare delicacies are piled in confusion, sons and concubines attend him—conduct opposite to antiquity." },
  { zh: "臣懼賢等專守一城，言攻於西而羌出於東，且其將士將不堪命，必有高克潰叛之變也。", literal: "Your servant fears Xian and others will only hold one city, speaking of attack in the west while Qiang emerge in the east, and that his officers and soldiers will not bear their orders—there will surely be mutiny and collapse like at Gaokeng.", idiomatic: "Your servant fears Ma Xian and others will only hold one city, speaking of attack in the west while Qiang emerge in the east, and that his officers and soldiers will not bear their orders—there will surely be mutiny and collapse like at Gaokeng." },
  { zh: "」安定人皇甫規亦見賢不恤軍事，審其必敗，上書言狀。", literal: "\" Huangfu Gui of Anding also saw that Xian did not care for military affairs, was sure he would fail, and submitted a memorial stating the facts.", idiomatic: "\" Huangfu Gui of Anding also saw that Ma Xian did not care for military affairs, was sure he would fail, and submitted a memorial stating the facts." },
  { zh: "朝廷皆不從。", literal: "The court would not follow any of this.", idiomatic: "The court would not follow any of this." },
  { zh: "春，正月，丙子，征西將軍馬賢與且凍羌戰於射姑山，賢軍敗；", literal: "In spring, the first month, on bingzi, General Who Pacifies the West Ma Xian fought the Qiandong Qiang at Mount Shegu, and Xian's army was defeated;", idiomatic: "In spring, in the first month, on bingzi day, General Who Pacifies the West Ma Xian fought the Qiandong Qiang at Mount Shegu, and Xian's army was defeated;" },
  { zh: "賢及二子皆沒，東、西羌遂大合。", literal: "Xian and his two sons all perished, and the Eastern and Western Qiang then joined in great union.", idiomatic: "Ma Xian and his two sons all perished, and the Eastern and Western Qiang then joined in great union." },
  { zh: "閏月，鞏唐羌寇隴西，遂及三輔，燒園陵，殺掠吏民。", literal: "In the intercalary month, the Gongtang Qiang raided Longxi, reached the Three Assistants, burned the park tombs, and killed and plundered officials and people.", idiomatic: "In the intercalary month, the Gongtang Qiang raided Longxi, reached the Three Assistants, burned the park tombs, and killed and plundered officials and people." },
  { zh: "二月，丁巳，有星孛於營室。", literal: "In the second month, on dingsi, a comet appeared in the Lodgings.", idiomatic: "In the second month, on dingsi day, a comet appeared in the Lodgings." },
  { zh: "三月，上巳，大將軍商大會賓客，宴於雒水；", literal: "In the third month, on Shangsi, Grand General-in-Chief Shang greatly gathered guests and feasted at the Luo River;", idiomatic: "In the third month, on Shangsi, Grand General-in-Chief Liang Shang greatly gathered guests and feasted at the Luo River;" },
  { zh: "酒闌，繼以《韭露之歌》。", literal: "when the wine was ending they followed with the \"Song of Leek Dew.\"", idiomatic: "when the wine was ending they followed with the \"Song of Leek Dew.\"" },
  { zh: "從事中郎周舉聞之，歎曰：「此所謂哀樂失時，非其所也，殃將及乎！", literal: "Attendant Gentleman Zhou Ju heard this and sighed, saying: \"This is what is called joy and mourning out of season, not in their proper place—calamity will reach us!", idiomatic: "Attendant Gentleman Zhou Ju heard this and sighed, saying, \"This is what is called joy and mourning out of season, not in their proper place—calamity will reach us!" },
  { zh: "武都太守趙沖追擊鞏唐羌，斬首四百餘級，降二千餘人。", literal: "Administrator of Wudou Zhao Chong pursued the Gongtang Qiang, took more than four hundred heads, and received more than two thousand surrenders.", idiomatic: "Administrator of Wudou Zhao Chong pursued the Gongtang Qiang, took more than four hundred heads, and received more than two thousand surrenders." },
  { zh: "詔沖督河西四郡兵為節度。", literal: "An edict made Chong supervise the armies of the four Hexi commanderies as coordinator.", idiomatic: "An edict made Zhao Chong supervise the armies of the four Hexi commanderies as coordinator." },
  { zh: "安定上計掾皇甫規上疏曰：「臣比年以來，數陳便宜：羌戎未動，策其將反；", literal: "Anding's reporting clerk Huangfu Gui submitted a memorial, saying: \"Your servant in recent years has repeatedly set forth timely proposals: before the Qiang and Rong moved, I predicted they would rebel;", idiomatic: "Anding's reporting clerk Huangfu Gui submitted a memorial, saying, \"Your servant in recent years has repeatedly set forth timely proposals. Before the Qiang and Rong moved, I predicted they would rebel;" },
  { zh: "馬賢始出，知其必敗。", literal: "when Ma Xian first went out, I knew he would certainly fail.", idiomatic: "when Ma Xian first went out, I knew he would certainly fail." },
  { zh: "誤中之言，在可考校。", literal: "Words that hit by mistake are subject to verification.", idiomatic: "Words that hit by mistake are subject to verification." },
  { zh: "臣每惟賢等擁眾四年，未有成功，縣師之費，且百億計，出於平民，回入奸吏。", literal: "Your servant often reflects that Xian and others have held armies for four years without success; expenses for troops in the field exceed ten billion, taken from common people and circling back into corrupt officials.", idiomatic: "Your servant often reflects that Ma Xian and others have held armies for four years without success. Expenses for troops in the field exceed ten billion, taken from common people and circling back into corrupt officials." },
  { zh: "故江湖之人，群為盜賊，青、徐荒饑，襁負流散。", literal: "Therefore people of the rivers and lakes band together as bandits; Qing and Xu suffer famine and hunger, carrying infants in swaddling clothes and scattering in flight.", idiomatic: "Therefore people of the rivers and lakes band together as bandits. Qing and Xu suffer famine and hunger, carrying infants in swaddling clothes and scattering in flight." },
  { zh: "夫羌戎潰叛，不由承平，皆因邊將失於綏御，乘常守安則加侵暴，苟競小利則致大害，微勝則虛張首級，軍敗則隱匿不言。", literal: "The Qiang and Rong's collapse and rebellion do not come from long peace—all stem from frontier generals failing in pacification and control: when taking advantage of routine security they add invasion and violence; when competing for petty gain they bring great harm; slight victory they inflate with false head counts, defeat they hide and do not report.", idiomatic: "The Qiang and Rong's collapse and rebellion do not come from long peace—all stem from frontier generals failing in pacification and control. When taking advantage of routine security they add invasion and violence; when competing for petty gain they bring great harm. Slight victory they inflate with false head counts; defeat they hide and do not report." },
  { zh: "軍士勞怨，困於猾吏，進不得快戰以徼功，退不得溫飽以全命，餓死溝渠，暴骨中原；", literal: "Soldiers labor and resent, trapped by cunning clerks—advancing they cannot fight swiftly to win merit, retreating they cannot get warmth and food to preserve life; they starve dead in ditches and drains, bones exposed in the central plains;", idiomatic: "Soldiers labor and resent, trapped by cunning clerks—advancing they cannot fight swiftly to win merit, retreating they cannot get warmth and food to preserve life. They starve dead in ditches and drains, bones exposed in the central plains;" },
  { zh: "徒見王師之出，不聞振旅之聲。", literal: "one only sees the royal army go forth, never hears the sound of troops returning triumphant.", idiomatic: "one only sees the royal army go forth, never hears the sound of troops returning triumphant." },
  { zh: "酋豪泣血，驚懼生變，是以安不能久，叛則經年，臣所以搏手扣心而增歎者也！", literal: "Chieftains weep blood, startled fear breeds change—thus peace cannot last long and rebellion lasts years; this is why your servant claps his hands and strikes his heart with added sighs!", idiomatic: "Chieftains weep blood, startled fear breeds change—thus peace cannot last long and rebellion lasts years. This is why your servant claps his hands and strikes his heart with added sighs!" },
  { zh: "願假臣兩營、二郡屯列坐食之兵五千，出其不意，與趙沖共相首尾。", literal: "Your servant wishes to be lent five thousand men from two camps and two commanderies who sit and eat at their stations, strike with surprise, and coordinate head and tail with Zhao Chong.", idiomatic: "Your servant wishes to be lent five thousand men from two camps and two commanderies who sit and eat at their stations, strike with surprise, and coordinate head and tail with Zhao Chong." },
  { zh: "土地山谷，臣所曉習；", literal: "The land's mountains and valleys your servant knows well;", idiomatic: "The land's mountains and valleys your servant knows well;" },
  { zh: "兵勢巧便，臣已更之；", literal: "military formations' cunning and convenience your servant has already revised;", idiomatic: "military formations' cunning and convenience your servant has already revised;" },
  { zh: "可不煩方寸之印，尺帛之賜，高可以滌患，下可以納降。", literal: "without troubling an inch-square seal or a foot of silk reward—above it can wash away calamity, below it can receive surrender.", idiomatic: "without troubling an inch-square seal or a foot of silk reward—above it can wash away calamity, below it can receive surrender." },
  { zh: "若謂臣年少、官輕，不足用者，凡諸敗將，非官爵之不高，年齒之不邁。", literal: "If you say your servant is young and his office light and not sufficient to use—for all the defeated generals, it was not that rank was not high or years not advanced.", idiomatic: "If you say your servant is young and his office light and not sufficient to use—for all the defeated generals, it was not that rank was not high or years not advanced." },
  { zh: "臣不勝至誠，沒死自陳！", literal: "Your servant cannot overcome utmost sincerity and offers this even unto death!", idiomatic: "Your servant cannot overcome utmost sincerity and offers this even unto death!" },
  { zh: "」帝不能用。", literal: "\" The emperor could not employ him.", idiomatic: "\" The emperor could not employ him." },
  { zh: "庚子，司空郭虔免。", literal: "On gengzi, Minister of Works Guo Qian was dismissed.", idiomatic: "On gengzi day, Minister of Works Guo Qian was dismissed." },
  { zh: "丙午，以太僕趙戒為司空。", literal: "On bingwu, Grand Master of Transport Zhao Jie was made Minister of Works.", idiomatic: "On bingwu day, Grand Master of Transport Zhao Jie was made Minister of Works." },
  { zh: "夏，使匈奴中郎將張耽、度遼將軍馬續率鮮卑到谷城，擊烏桓於通天山，大破之。", literal: "In summer, the Xiongnu Colonel Zhang Dan and Crossing-the-Desert General Ma Xu led the Xianbei to Gucheng and attacked the Wuhuan at Mount Tongtian, routing them greatly.", idiomatic: "In summer, the Xiongnu Colonel Zhang Dan and Crossing-the-Desert General Ma Xu led the Xianbei to Gucheng and attacked the Wuhuan at Mount Tongtian, routing them greatly." },
  { zh: "鞏唐羌寇北地。", literal: "The Gongtang Qiang raided Beidi.", idiomatic: "The Gongtang Qiang raided Beidi." },
  { zh: "北地太守賈福與趙衝擊之，不利。", literal: "Beidi Administrator Jia Fu with Zhao Chong attacked them but with unfavorable result.", idiomatic: "Beidi Administrator Jia Fu with Zhao Chong attacked them but with unfavorable result." },
  { zh: "秋，八月，乘氏忠侯梁商病篤，敕子冀等曰：「吾生無以輔益朝廷，死何可耗費帑藏！", literal: "In autumn, the eighth month, Loyal Marquis of Chengshi Liang Shang was gravely ill and instructed his sons Ji and the others, saying: \"In life I had nothing by which to aid and benefit the court—in death how can I waste the treasury!", idiomatic: "In autumn, in the eighth month, Loyal Marquis of Chengshi Liang Shang was gravely ill and instructed his sons Ji and the others, saying, \"In life I had nothing by which to aid and benefit the court—in death how can I waste the treasury!" },
  { zh: "衣衾、飯含、玉匣、珠貝之屬，何益朽骨！", literal: "Garments, grave offerings, jade cases, pearls and shells—what good to rotted bones!", idiomatic: "Garments, grave offerings, jade cases, pearls and shells—what good to rotted bones!" },
  { zh: "百僚勞擾，紛華道路，只增塵垢耳。", literal: "A hundred officials labor and disturb, splendor fills the roads—this only adds dust and filth.", idiomatic: "A hundred officials labor and disturb, splendor fills the roads—this only adds dust and filth." },
  { zh: "宜皆辭之。", literal: "You should all decline these.\"", idiomatic: "You should all decline these.\"" },
  { zh: "」丙辰，薨；", literal: "\" On bingchen, he died;", idiomatic: "\" On bingchen day, he died;" },
  { zh: "帝親臨喪。", literal: "the emperor personally attended the mourning.", idiomatic: "The emperor personally attended the mourning." },
  { zh: "諸子欲從其誨，朝廷不聽，賜以東園秘器、銀鏤、黃腸、玉匣。", literal: "The sons wished to follow his teaching but the court would not hear it and bestowed the Eastern Garden secret coffin ware, silver inlay, yellow cypress, and jade case.", idiomatic: "The sons wished to follow his teaching but the court would not hear it and bestowed the Eastern Garden secret coffin ware, silver inlay, yellow cypress, and jade case." },
  { zh: "及葬，賜輕車、介士，中宮親送。", literal: "At the burial they were granted light carriages and armed guards; the inner palace personally escorted.", idiomatic: "At the burial they were granted light carriages and armed guards. The inner palace personally escorted." },
  { zh: "帝至宣陽亭，瞻望車騎。", literal: "The emperor went to Xuanyang Pavilion and gazed upon the carriage and escort.", idiomatic: "The emperor went to Xuanyang Pavilion and gazed upon the carriage and escort." },
  { zh: "壬戌，以河南尹、乘氏侯梁冀為大將軍，冀弟侍中不疑為河南伊。", literal: "On renxu, Henan Intendant and Marquis of Chengshi Liang Ji was made Grand General-in-Chief, and Ji's younger brother Palace Attendant Buyi was made Intendant of Henan.", idiomatic: "On renxu day, Henan Intendant and Marquis of Chengshi Liang Ji was made Grand General-in-Chief, and Ji's younger brother Palace Attendant Buyi was made Intendant of Henan." },
  { zh: "臣光曰：成帝不能選任賢俊，委政舅家，可謂暗矣；", literal: "Subject Guang said: Emperor Cheng could not select and appoint worthy and talented men, entrusted government to the maternal kin—it may be called dim;", idiomatic: "Sima Guang remarks: Emperor Cheng could not select and appoint worthy and talented men and entrusted government to the maternal kin—it may be called dim;" },
  { zh: "猶知王立之不材，棄而不用。", literal: "yet he still knew Wang Li's lack of ability and discarded him without using him.", idiomatic: "yet he still knew Wang Li's lack of ability and discarded him without using him." },
  { zh: "順帝援大柄，授之後族，梁冀頑嚚凶暴，著於平昔，而使之繼父之位，終於悖逆，蕩覆漢室；", literal: "Emperor Shun took up the great handle and gave it to the empress's clan—Liang Ji was obstinate, foolish, fierce, and violent, evident from the past—yet had him succeed his father's position, ending in perversity and overturning the Han house;", idiomatic: "Emperor Shun took up the great handle and gave it to the empress's clan. Liang Ji was obstinate, foolish, fierce, and violent, evident from the past, yet was made to succeed his father's position, ending in perversity and overturning the Han house;" },
  { zh: "校於成帝，暗又甚焉！", literal: "Compared with Emperor Cheng, he was even dimmer!", idiomatic: "Compared with Emperor Cheng, he was even dimmer!" },
  { zh: "初，梁商病篤，帝親臨幸，問以遺言。", literal: "Earlier, when Liang Shang was gravely ill, the emperor personally visited and asked his last words.", idiomatic: "Earlier, when Liang Shang was gravely ill, the emperor personally visited and asked his last words." },
  { zh: "對曰：「臣從事中郎周舉，清高忠正，可重任也。", literal: "He replied: \"Your servant's Attendant Gentleman Zhou Ju is pure, lofty, loyal, and upright—he may be heavily entrusted.", idiomatic: "He replied, \"Your servant's Attendant Gentleman Zhou Ju is pure, lofty, loyal, and upright—he may be heavily entrusted." },
  { zh: "」由是拜舉諫議大夫。", literal: "\" Thereupon Ju was appointed Grandee Remonstrator.", idiomatic: "\" Thereupon Zhou Ju was appointed Grandee Remonstrator." },
  { zh: "九月，諸羌寇武威。", literal: "In the ninth month, the various Qiang raided Wuwei.", idiomatic: "In the ninth month, the various Qiang raided Wuwei." },
  { zh: "辛亥晦，日有食之。", literal: "On the last day of the month, xinhai, there was a solar eclipse.", idiomatic: "On the last day of the month, xinhai day, there was a solar eclipse." },
  { zh: "冬，十月，癸丑，以羌寇充斥，涼部震恐，復徙安定居扶風，北地居馮翊。", literal: "In winter, the tenth month, on guichou, because Qiang raiders filled the region and Liang province trembled in fear, Anding was again moved to lodge in Fufeng and Beidi in Fengyi.", idiomatic: "In winter, in the tenth month, on guichou day, because Qiang raiders filled the region and Liang province trembled in fear, Anding was again moved to lodge in Fufeng and Beidi in Fengyi." },
  { zh: "十一月，庚子，以執金吾張喬行車騎將軍事，將兵萬五千人屯三輔。", literal: "In the eleventh month, on gengzi, Chief Commandant of Justice Zhang Qiao was made to act as General of Chariots and Cavalry Affairs, leading fifteen thousand troops garrisoned in the Three Assistants.", idiomatic: "In the eleventh month, on gengzi day, Chief Commandant of Justice Zhang Qiao was made to act as General of Chariots and Cavalry Affairs, leading fifteen thousand troops garrisoned in the Three Assistants." },
  { zh: "荊州盜賊起，彌年不定；", literal: "Bandits rose in Jing province and for a year were not settled;", idiomatic: "Bandits rose in Jing province and for a year were not settled;" },
  { zh: "以大將軍從事中郎李固為荊州刺史。", literal: "Attendant Gentleman of the Grand General-in-Chief Li Gu was made Inspector of Jing province.", idiomatic: "Attendant Gentleman of the Grand General-in-Chief Li Gu was made Inspector of Jing province." },
  { zh: "固到，遣吏勞問境內，赦寇盜前釁，與之更始。", literal: "When Gu arrived he sent officials to comfort and inquire within the borders, pardoned the bandits' prior offenses, and gave them a fresh start.", idiomatic: "When Li Gu arrived he sent officials to comfort and inquire within the borders, pardoned the bandits' prior offenses, and gave them a fresh start." },
  { zh: "於是賊帥夏密等率其魁黨六百餘人自縛歸首，固皆原之，遣還，使自相招集，開示威法；", literal: "Thereupon the bandit chief Xia Mi and others led more than six hundred chiefs and followers to bind themselves and surrender; Gu all pardoned them, sent them back, had them gather one another, and opened and displayed the laws of authority;", idiomatic: "Thereupon the bandit chief Xia Mi and others led more than six hundred chiefs and followers to bind themselves and surrender. Li Gu all pardoned them, sent them back, had them gather one another, and opened and displayed the laws of authority;" },
  { zh: "半歲間，餘類悉降，州內清平。", literal: "within half a year the remaining groups all surrendered and the province was clear and at peace.", idiomatic: "Within half a year the remaining groups all surrendered and the province was clear and at peace." },
  { zh: "奏南陽太守高賜等臧穢；", literal: "He memorialized that Administrator of Nanyang Gao Ci and others were corrupt;", idiomatic: "He memorialized that Administrator of Nanyang Gao Ci and others were corrupt;" },
  { zh: "賜等重賂大將軍梁冀，冀為之千里移檄，而固持之愈急，冀遂徙固為泰山太守。", literal: "Ci and others heavily bribed Grand General Liang Ji; Ji for them sent a proclamation a thousand li away, yet Gu held firm ever more urgently, and Ji thereupon transferred Gu to be Administrator of Taishan.", idiomatic: "Ci and others heavily bribed Grand General Liang Ji. Ji for them sent a proclamation a thousand li away, yet Li Gu held firm ever more urgently, and Ji thereupon transferred Li Gu to be Administrator of Taishan." },
  { zh: "時泰山盜賊屯聚歷年，郡兵常千人追討，不能制；", literal: "At the time bandits in Taishan had gathered for years; commandery troops, often a thousand men in pursuit, could not control them;", idiomatic: "At the time bandits in Taishan had gathered for years. Commandery troops, often a thousand men in pursuit, could not control them;" },
  { zh: "固到，悉罷遣歸農，但選留任戰者百餘人，以恩信招誘之。", literal: "When Gu arrived, he dismissed all and sent them back to farming, selecting only a little more than a hundred fit for battle to remain, and with kindness and trust summoned and enticed the bandits.", idiomatic: "When Li Gu arrived, he dismissed all the troops and sent them back to farming, selecting only a little more than a hundred fit for battle to remain, and with kindness and trust summoned and enticed the bandits." },
  { zh: "未滿歲，賊皆弭散。", literal: "Before a full year had passed, the bandits all dispersed and submitted.", idiomatic: "Before a full year had passed, the bandits all dispersed and submitted." },
  { zh: "春，正月，癸巳，赦天下，改元。", literal: "In spring, the first month, on guisi day, amnestied the realm and changed the reign title.", idiomatic: "In spring, in the first month, on guisi day, the realm was amnestied and the reign title was changed." },
  { zh: "秋，八月，南匈奴句龍吾斯與薁鞬、台耆等復反，寇掠並部。", literal: "In autumn, the eighth month, the Southern Xiongnu Goulong Wusi together with Wujian, Taiqi, and others again rebelled and raided Bing province.", idiomatic: "In autumn, in the eighth month, the Southern Xiongnu Goulong Wusi together with Wujian, Taiqi, and others again rebelled and raided Bing province." },
  { zh: "丁卯，遺侍中河內杜喬、周舉、守光祿大夫周栩、馮羨、魏郡欒巴、張綱、郭遵、劉班分行州郡，表賢良，顯忠勤；", literal: "On dingmao day, sent Palace Attendant Du Qiao of Henei, Zhou Ju, Acting Grand Master of Splendid Happiness Zhou Xu, Feng Xian, Luan Ba of Wei commandery, Zhang Gang, Guo Zun, and Liu Ban to tour the commanderies and states separately, to memorialize the worthy and good, and display loyalty and diligence;", idiomatic: "On dingmao day, Palace Attendant Du Qiao of Henei, Zhou Ju, Acting Grand Master of Splendid Happiness Zhou Xu, Feng Xian, Luan Ba of Wei commandery, Zhang Gang, Guo Zun, and Liu Ban were sent to tour the commanderies and states separately, to memorialize the worthy and good, and display loyalty and diligence;" },
  { zh: "其貪污有罪者，刺史、二千石驛馬上之，墨綬以下便輒收舉。", literal: "as for the corrupt and guilty, governors and two-thousand-bushel officials were to report them by relay horse, and those below black seal were at once to be arrested and impeached.", idiomatic: "as for the corrupt and guilty, governors and two-thousand-bushel officials were to report them by relay horse, and those below black seal were at once to be arrested and impeached." },
  { zh: "喬等受命之部，張綱獨埋其車輪於雒陽都亭，曰：「豺狼當路，安問狐狸！", literal: "Qiao and the others received the command and went to their regions; Zhang Gang alone buried his carriage wheels at the Luoyang capital post station, saying: \"When jackals and wolves block the road, why ask about foxes!", idiomatic: "Qiao and the others received the command and went to their regions. Zhang Gang alone buried his carriage wheels at the Luoyang capital post station, saying, \"When jackals and wolves block the road, why ask about foxes!" },
  { zh: "」遂劾奏：「大將軍冀、河南尹不疑，以外戚蒙恩，居阿衡之任，而專肆貪叨，縱恣無極，多樹諂諛以害忠良，誠天威所不赦，大辟所宜加也。", literal: "\" Thereupon he impeached and memorialized: \"Grand General Ji and Intendant of Henan Bu Yi, as maternal kin receiving grace, holding the task of supporting the balance, yet exclusively indulging greed, dissolute without limit, planting many flatterers to harm the loyal and good—truly what heaven's majesty does not pardon and what the great execution should be applied to.", idiomatic: "\" Thereupon he impeached and memorialized, \"Grand General Ji and Intendant of Henan Bu Yi, as maternal kin receiving grace, holding the task of supporting the balance, yet exclusively indulging greed, dissolute without limit, planting many flatterers to harm the loyal and good—truly what heaven's majesty does not pardon and what the great execution should be applied to." },
  { zh: "謹條其無君之心十五事，斯皆臣子所切齒者也。", literal: "\" Your servant respectfully lists fifteen matters of his heart without a ruler—all these are what ministers and sons gnash their teeth at.", idiomatic: "\" Your servant respectfully lists fifteen matters of his heart without a ruler—all these are what ministers and sons gnash their teeth at." },
  { zh: "」書御，京師震竦。", literal: "\" The memorial reached the throne; the capital trembled in awe.", idiomatic: "\" The memorial reached the throne. The capital trembled in awe." },
  { zh: "時皇后寵方盛，諸梁姻族滿朝，帝雖知綱言直，不能用也。", literal: "At the time the empress's favor was flourishing; all the Liang affinal kin filled the court. Though the emperor knew Gang's words were straight, he could not use them.", idiomatic: "At the time the empress's favor was flourishing and all the Liang affinal kin filled the court. Though the emperor knew Gang's words were straight, he could not use them." },
  { zh: "杜喬至冶金兗州，表奏泰山太守李固政為天下第一，上征固為將作大匠。", literal: "Du Qiao reached Yanzhou and memorialized that Administrator of Taishan Li Gu's government was first under heaven; the emperor summoned Gu to be Master of Works.", idiomatic: "Du Qiao reached Yanzhou and memorialized that Administrator of Taishan Li Gu's government was first under heaven. The emperor summoned Li Gu to be Master of Works." },
  { zh: "八使所劾奏，多梁冀及宦者親黨；", literal: "What the eight envoys impeached and memorialized was mostly Liang Ji and the eunuchs' kin and partisans;", idiomatic: "What the eight envoys impeached and memorialized was mostly Liang Ji and the eunuchs' kin and partisans;" },
  { zh: "互為請救，事皆寢遏。", literal: "they pleaded for one another's rescue, and all matters were suppressed and blocked.", idiomatic: "they pleaded for one another's rescue, and all matters were suppressed and blocked." },
  { zh: "侍御史河南種暠疾之，復行案舉。", literal: "Attending Clerk Zhong Hao of Henan hated this and again carried out investigation and impeachment.", idiomatic: "Attending Clerk Zhong Hao of Henan hated this and again carried out investigation and impeachment." },
  { zh: "廷尉吳雄、將作大匠李固亦上言：「八使所糾，宜急誅罰。", literal: "Minister of Justice Wu Xiong and Master of Works Li Gu also submitted words: \"What the eight envoys impeached should urgently be executed and punished.", idiomatic: "Minister of Justice Wu Xiong and Master of Works Li Gu also submitted words, \"What the eight envoys impeached should urgently be executed and punished." },
  { zh: "」帝乃更下八使奏章，令考正其罪。", literal: "\" The emperor thereupon again sent down the eight envoys' memorials and ordered examination and correction of their crimes.", idiomatic: "\" The emperor thereupon again sent down the eight envoys' memorials and ordered examination and correction of their crimes." },
  { zh: "梁冀恨張綱，思有以中傷之。", literal: "Liang Ji hated Zhang Gang and sought some means to strike him within.", idiomatic: "Liang Ji hated Zhang Gang and sought some means to strike him within." },
  { zh: "時廣陵賊張嬰寇亂揚、徐間積十餘年，二千石不能制，冀乃以綱為廣陵太守。", literal: "At the time the bandit of Guangling Zhang Ying had raided and disturbed Yang and Xu for more than ten years; two-thousand-bushel officials could not control him, and Ji thereupon made Gang Administrator of Guangling.", idiomatic: "At the time the bandit of Guangling Zhang Ying had raided and disturbed Yang and Xu for more than ten years. Two-thousand-bushel officials could not control him, and Ji thereupon made Gang Administrator of Guangling." },
  { zh: "前太守率多求兵馬，綱獨請單車之職。", literal: "Former administrators mostly requested troops and horses; Gang alone requested the duty with a single carriage.", idiomatic: "Former administrators mostly requested troops and horses. Gang alone requested the duty with a single carriage." },
  { zh: "既到，逕詣嬰壘門；", literal: "When he had arrived, he went straight to Ying's camp gate;", idiomatic: "When he had arrived, he went straight to Ying's camp gate;" },
  { zh: "嬰大驚，遽走閉壘。", literal: "Ying was greatly alarmed and hastily ran to shut the camp.", idiomatic: "Ying was greatly alarmed and hastily ran to shut the camp." },
  { zh: "綱於門外罷遣吏兵，獨留所親者十餘人，以書喻嬰，請與相見。", literal: "Gang outside the gate dismissed clerks and soldiers, keeping only a little more than ten of his intimates, and with a letter instructed Ying, requesting to meet face to face.", idiomatic: "Gang outside the gate dismissed clerks and soldiers, keeping only a little more than ten of his intimates, and with a letter instructed Ying, requesting to meet face to face." },
  { zh: "嬰見綱至誠，乃出拜謁。", literal: "Ying, seeing Gang's utmost sincerity, then came out to bow and call on him.", idiomatic: "Ying, seeing Gang's utmost sincerity, then came out to bow and call on him." },
  { zh: "綱延置上坐，譬之曰：「前後二千石多肆貪暴，故致公等懷憤相聚。", literal: "Gang received him and set him in the upper seat, admonishing him, saying: \"Former and later two-thousand-bushel officials mostly indulged greed and violence, and so caused you gentlemen to harbor resentment and gather together.", idiomatic: "Gang received him and set him in the upper seat, admonishing him, saying, \"Former and later two-thousand-bushel officials mostly indulged greed and violence, and so caused you gentlemen to harbor resentment and gather together." },
  { zh: "二千石信有罪矣，然為之者又非義也。", literal: "\" The two-thousand-bushel officials truly have offense, yet what you do is also not righteous.", idiomatic: "\" The two-thousand-bushel officials truly have offense, yet what you do is also not righteous." },
  { zh: "今主上仁聖，欲以文德服叛，故遣太守來，思以爵祿相榮，不願以刑罰相加，今誠轉禍為福之時也。", literal: "\" Now the sovereign is benevolent and sage, wishing with civil virtue to subdue rebels, and so sent the administrator to come, thinking to honor you with rank and salary and not wishing to add punishments—now is truly the time to turn disaster into blessing.", idiomatic: "\" Now the sovereign is benevolent and sage, wishing with civil virtue to subdue rebels, and so sent the administrator to come, thinking to honor you with rank and salary and not wishing to add punishments—now is truly the time to turn disaster into blessing." },
  { zh: "若聞義不服，天子赫然震怒，荊、揚、兗、豫大兵雲合，身首橫分，血嗣俱絕。", literal: "\" If on hearing righteousness you do not submit, the Son of Heaven will blaze in anger; great armies of Jing, Yang, Yan, and Yu will gather like clouds, bodies and heads cut apart, blood descendants all extinguished.", idiomatic: "\" If on hearing righteousness you do not submit, the Son of Heaven will blaze in anger. Great armies of Jing, Yang, Yan, and Yu will gather like clouds, bodies and heads cut apart, blood descendants all extinguished." },
  { zh: "二者利害，公其深計之！", literal: "\" Of the two, benefit and harm—you gentlemen should deeply calculate them!", idiomatic: "\" Of the two, benefit and harm—you gentlemen should deeply calculate them!" },
  { zh: "」嬰聞，泣下曰：「荒裔愚民，不能自通朝廷，不堪侵枉，遂復相聚偷生，若魚游釜中，知其不可久，且以喘息須臾間耳！", literal: "\" Ying on hearing wept and said: \"Your servant is a foolish man of the wild borderlands, unable to reach the court on his own, unable to bear oppression and wrong, and so again gathered to steal life, like fish swimming in a cauldron—knowing it cannot last long, only gasping for breath in a brief moment!", idiomatic: "\" Ying on hearing wept and said, \"Your servant is a foolish man of the wild borderlands, unable to reach the court on his own, unable to bear oppression and wrong, and so again gathered to steal life, like fish swimming in a cauldron—knowing it cannot last long, only gasping for breath in a brief moment!" },
  { zh: "今聞明府之言，乃嬰等更生之辰也！", literal: "\" Now on hearing the enlightened prefect's words, this is the hour when Ying and the rest are born again!", idiomatic: "\" Now on hearing the enlightened prefect's words, this is the hour when Ying and the rest are born again!" },
  { zh: "」乃辭還營。", literal: "\" Thereupon he took leave and returned to camp.", idiomatic: "\" Thereupon he took leave and returned to camp." },
  { zh: "明日，將所部萬餘人與妻子面縛歸降。", literal: "The next day he led his following of more than ten thousand men, with wives and children, bound face-forward and came to surrender.", idiomatic: "The next day he led his following of more than ten thousand men, with wives and children, bound face-forward and came to surrender." },
  { zh: "綱單車入嬰壘，大會，置酒為樂，散遣部眾，任從所之；", literal: "Gang with a single carriage entered Ying's camp, held a great assembly, set out wine for joy, and dispersed and sent off the troops, letting them go where they wished;", idiomatic: "Gang with a single carriage entered Ying's camp, held a great assembly, set out wine for joy, and dispersed and sent off the troops, letting them go where they wished;" },
  { zh: "親為卜居宅、相田疇；", literal: "he personally chose dwelling sites and surveyed fields for them;", idiomatic: "he personally chose dwelling sites and surveyed fields for them;" },
  { zh: "子弟欲為吏者，皆引召之。", literal: "sons and younger brothers who wished to become officials were all summoned and appointed.", idiomatic: "sons and younger brothers who wished to become officials were all summoned and appointed." },
  { zh: "人情悅服，南州晏然。", literal: "Human hearts were pleased and submitted; the southern province was peaceful.", idiomatic: "Human hearts were pleased and submitted. The southern province was peaceful." },
  { zh: "朝廷論功當封，梁冀遏之。", literal: "The court deliberated on merit and he should have been enfeoffed, but Liang Ji blocked it.", idiomatic: "The court deliberated on merit and he should have been enfeoffed, but Liang Ji blocked it." },
  { zh: "在郡一歲，卒；", literal: "After one year in the commandery he died;", idiomatic: "After one year in the commandery he died;" },
  { zh: "張嬰等五百餘人為之制服行喪，送到犍為，負土成墳。", literal: "Zhang Ying and more than five hundred others wore mourning for him and conducted the funeral, escorting him to Qianwei and piling earth to make his mound.", idiomatic: "Zhang Ying and more than five hundred others wore mourning for him and conducted the funeral, escorting him to Qianwei and piling earth to make his mound." },
  { zh: "詔拜其子續為郎中，賜錢百萬。", literal: "An edict appointed his son Xu as Gentleman of the Palace, bestowing a million cash.", idiomatic: "An edict appointed his son Xu as Gentleman of the Palace, bestowing a million cash." },
  { zh: "是時，二千石長吏有能政者，有雒陽令渤海任峻、冀州刺史京兆蘇章、膠東相陳留吳祐。", literal: "At the time among chief officials of two thousand bushels who had able government were Magistrate of Luoyang Ren Jun of Bohai, Governor of Ji Su Zhang of Jingzhao, and Chancellor of Jiaodong Wu You of Chenliu.", idiomatic: "At the time among chief officials of two thousand bushels who had able government were Magistrate of Luoyang Ren Jun of Bohai, Governor of Ji Su Zhang of Jingzhao, and Chancellor of Jiaodong Wu You of Chenliu." },
  { zh: "雒陽令自王渙之後，皆不稱職。", literal: "Magistrates of Luoyang since Wang Huan had none been fit for their duties.", idiomatic: "Magistrates of Luoyang since Wang Huan had none been fit for their duties." },
  { zh: "峻能選用文武吏，各盡其用，發奸不旋踵，民間不畏吏，其威禁猛於渙，而文理政教不如也。", literal: "Jun could select and employ civil and military clerks, each fulfilling his use; exposing wickedness without turning the heel—the people in the lanes did not fear clerks. His authority and prohibitions were fiercer than Huan's, yet in culture, principle, government, and instruction he was not equal.", idiomatic: "Jun could select and employ civil and military clerks, each fulfilling his use, exposing wickedness without turning the heel—the people in the lanes did not fear clerks. His authority and prohibitions were fiercer than Huan's, yet in culture, principle, government, and instruction he was not equal." },
  { zh: "章為冀州刺史，有故人為清河太守，章行部，欲案其奸臧，乃主太守為設酒餚，陳平生之好甚歡。", literal: "Zhang was Governor of Ji; an old friend was Administrator of Qinghe. When Zhang toured the department and wished to investigate his corruption, the host administrator set out wine and food for him and spoke of their lifelong friendship very pleasantly.", idiomatic: "Su Zhang was Governor of Ji. An old friend was Administrator of Qinghe. When Zhang toured the department and wished to investigate his corruption, the host administrator set out wine and food for him and spoke of their lifelong friendship very pleasantly." },
  { zh: "太守喜曰：「人皆有一天，我獨有二天！", literal: "The administrator rejoiced and said: \"Others all have one heaven; I alone have two heavens!", idiomatic: "The administrator rejoiced and said, \"Others all have one heaven. I alone have two heavens!" },
  { zh: "」章曰：「今夕蘇孺文與故人飲者，私恩也；", literal: "\" Zhang said: \"Tonight Su Ruwen drinking with an old friend is private favor;", idiomatic: "\" Zhang said, \"Tonight Su Ruwen drinking with an old friend is private favor;" },
  { zh: "明日冀州刺史案事者，公法也。", literal: "\" tomorrow the Governor of Ji investigating the case is public law.", idiomatic: "\" tomorrow the Governor of Ji investigating the case is public law." },
  { zh: "」遂舉正其罪，州境肅然。", literal: "\" Thereupon he impeached and corrected his crime; within the province all was orderly.", idiomatic: "\" Thereupon he impeached and corrected his crime. Within the province all was orderly." },
  { zh: "後以摧折權豪忤旨，坐免。", literal: "Later because he crushed the powerful and great and offended the imperial will, he was dismissed by offense.", idiomatic: "Later because he crushed the powerful and great and offended the imperial will, he was dismissed by offense." },
  { zh: "時天下日敝，民多愁苦，論者日夜稱章，朝廷遂不能復用也。", literal: "At the time the realm daily declined and the people had much sorrow and suffering; debaters day and night praised Zhang, yet the court in the end could not employ him again.", idiomatic: "At the time the realm daily declined and the people had much sorrow and suffering. Debaters day and night praised Zhang, yet the court in the end could not employ him again." },
  { zh: "祐為膠東相，政崇仁簡，民不忍欺。", literal: "You was Chancellor of Jiaodong; his government honored benevolence and simplicity, and the people could not bear to deceive him.", idiomatic: "Wu You was Chancellor of Jiaodong. His government honored benevolence and simplicity, and the people could not bear to deceive him." },
  { zh: "嗇夫孫性，私賦民錢，市衣以進其父，父得而怒曰：「有君如是，何忍欺之！", literal: "Revenue Officer Sun Xing privately levied the people's money, bought clothes, and presented them to his father. The father on receiving them angrily said: \"With a ruler like this, how can one bear to deceive him!", idiomatic: "Revenue Officer Sun Xing privately levied the people's money, bought clothes, and presented them to his father. The father on receiving them angrily said, \"With a ruler like this, how can one bear to deceive him!" },
  { zh: "」促歸伏罪。", literal: "\" He urged him to return and submit to punishment.", idiomatic: "\" He urged him to return and submit to punishment." },
  { zh: "性慚懼詣閣，持衣自首。", literal: "Xing in shame and fear went to the gate, holding the clothes to confess.", idiomatic: "Xing in shame and fear went to the gate, holding the clothes to confess." },
  { zh: "祐屏左右問其故，性具談父言。", literal: "You dismissed attendants and asked the reason; Xing fully related his father's words.", idiomatic: "You dismissed attendants and asked the reason. Xing fully related his father's words." },
  { zh: "祐曰：「掾以親故受污穢之名，所謂『觀過斯知仁矣。", literal: "You said: \"As a clerk you received a filthy name for kin's sake—what is called 'in observing faults one knows benevolence.", idiomatic: "You said, \"As a clerk you received a filthy name for kin's sake—what is called 'in observing faults one knows benevolence." },
  { zh: "』」使歸謝其父，還以衣遺之。", literal: "\"'\" He had him return to thank his father and gave back the clothes to him.", idiomatic: "\"'\" He had him return to thank his father and gave back the clothes to him." },
  { zh: "冬，十月，辛未，太尉桓焉、司徒劉壽免。", literal: "In winter, the tenth month, on xinwei day, Grand Commandant Huan Yan and Minister over the Masses Liu Shou were dismissed.", idiomatic: "In winter, in the tenth month, on xinwei day, Grand Commandant Huan Yan and Minister over the Masses Liu Shou were dismissed." },
  { zh: "罕羌邑落五千餘戶詣趙沖降，唯燒何種據參絲未下。", literal: "Qiang settlements of Han numbered more than five thousand households who came to Zhao Chong to surrender; only the Shaohe tribe held Cansi and had not submitted.", idiomatic: "Qiang settlements of Han numbered more than five thousand households who came to Zhao Chong to surrender. Only the Shaohe tribe held Cansi and had not submitted." },
  { zh: "甲戌，罷張喬軍屯。", literal: "On jiaxu day, Zhang Qiao's encamped army was disbanded.", idiomatic: "On jiaxu day, Zhang Qiao's encamped army was disbanded." },
  { zh: "十一月，壬午，以司隸校尉下邳趙峻為太尉，大司農胡廣為司徒。", literal: "In the eleventh month, on renwu day, made Colonel of the Metropolitan Area Zhao Jun of Xiapi Grand Commandant and Grand Minister of Agriculture Hu Guang Minister over the Masses.", idiomatic: "In the eleventh month, on renwu day, Colonel of the Metropolitan Area Zhao Jun of Xiapi was made Grand Commandant and Grand Minister of Agriculture Hu Guang was made Minister over the Masses." },
  { zh: "夏，四月，庚戌，護羌校尉趙沖與漢陽太守張貢擊燒當羌於參絲，破之。", literal: "In summer, the fourth month, on gengxu day, Colonel Protector of the Qiang Zhao Chong together with Administrator of Hanyang Zhang Gong attacked the Shaohe Qiang at Cansi and defeated them.", idiomatic: "In summer, in the fourth month, on gengxu day, Colonel Protector of the Qiang Zhao Chong together with Administrator of Hanyang Zhang Gong attacked the Shaohe Qiang at Cansi and defeated them." },
  { zh: "六月，丙寅，立南匈奴守義王兜樓儲為呼蘭若屍逐就單于。", literal: "In the sixth month, on bingyin day, established King of Upholding Righteousness of the Southern Xiongnu Dou Louchu as Chanyu Hulan Ruoshizhujiu.", idiomatic: "In the sixth month, on bingyin day, King of Upholding Righteousness of the Southern Xiongnu Dou Louchu was established as Chanyu Hulan Ruoshizhujiu." },
  { zh: "時兜樓儲在京師，上親臨軒授璽綬，引上殿，賜車馬、器服、金帛甚厚。", literal: "At the time Dou Louchu was in the capital; the emperor personally came to the hall to bestow the seal cord, led him up the hall, and bestowed carriage, horse, vessels, robes, gold, and silk very richly.", idiomatic: "At the time Dou Louchu was in the capital. The emperor personally came to the hall to bestow the seal cord, led him up the hall, and bestowed carriage, horse, vessels, robes, gold, and silk very richly." },
  { zh: "詔太常、大鴻臚與諸國侍子於廣陽城門外祖會，饗賜、作樂、角抵、百戲。", literal: "An edict ordered the Minister of Ceremonies and the Grand Herald together with the attendant sons of the various states to meet him in farewell outside the Guangyang city gate, with feasting, bestowals, music, grappling, and the hundred entertainments.", idiomatic: "An edict ordered the Minister of Ceremonies and the Grand Herald together with the attendant sons of the various states to meet him in farewell outside the Guangyang city gate, with feasting, bestowals, music, grappling, and the hundred entertainments." },
  { zh: "冬，閏十月，趙衝擊燒當羌於阿陽，破之。", literal: "In winter, the intercalary tenth month, Zhao Chong attacked the Shaohe Qiang at Ayang and defeated them.", idiomatic: "In winter, in the intercalary tenth month, Zhao Chong attacked the Shaohe Qiang at Ayang and defeated them." },
  { zh: "十一月，使匈奴中郎將扶風馬寔遣人刺殺句龍吾斯。", literal: "In the eleventh month, the envoy of the Xiongnu Central Colonel Ma Shi of Fufeng sent men to assassinate Goulong Wusi.", idiomatic: "In the eleventh month, the envoy of the Xiongnu Central Colonel Ma Shi of Fufeng sent men to assassinate Goulong Wusi." },
  { zh: "涼州自九月以來，地百八十震，山谷坼裂，壞敗城寺，民壓死者甚眾。", literal: "From the ninth month onward in Liang province the earth quaked one hundred eighty times; valleys split open; cities and temples were ruined; and among the people those crushed to death were very many.", idiomatic: "From the ninth month onward in Liang province the earth quaked one hundred eighty times. Valleys split open, cities and temples were ruined, and among the people those crushed to death were very many." },
  { zh: "尚書令黃瓊以前左雄所上孝廉之選，專用儒學、文吏，於取士之義猶有所遺，乃奏增孝悌及能從政者為四科；", literal: "Director of the Secretariat Huang Qiong, because the selection of Filial and Incorrupt candidates that Zuo Xiong formerly submitted used only Confucian learning and clerical officials, still had something missing in the meaning of taking scholars, and so memorialized to add Filial Piety and Fraternal Duty and those able to take part in government as four categories;", idiomatic: "Director of the Secretariat Huang Qiong, because the selection of Filial and Incorrupt candidates that Zuo Xiong formerly submitted used only Confucian learning and clerical officials, still had something missing in the meaning of taking scholars, and so memorialized to add Filial Piety and Fraternal Duty and those able to take part in government as four categories;" },
  { zh: "帝從之。", literal: "the emperor followed it.", idiomatic: "The emperor followed it." },
  { zh: "春，護羌從事馬玄為諸羌所誘，將羌眾亡出塞，領護羌校尉衛琚追擊玄等，斬首八百餘級。", literal: "In spring, Protector of the Qiang Attendant Ma Xuan was enticed by the various Qiang, led the Qiang masses in flight beyond the passes, and Colonel Protector of the Qiang Wei Ju pursued and attacked Xuan and the others, taking more than eight hundred heads.", idiomatic: "In spring, Protector of the Qiang Attendant Ma Xuan was enticed by the various Qiang, led the Qiang masses in flight beyond the passes, and Colonel Protector of the Qiang Wei Ju pursued and attacked Xuan and the others, taking more than eight hundred heads." },
  { zh: "趙沖復追叛羌到建威鸇陰河；", literal: "Zhao Chong again pursued rebel Qiang to Jianwei at the Zhuanyin River;", idiomatic: "Zhao Chong again pursued rebel Qiang to Jianwei at the Zhuanyin River;" },
  { zh: "軍度竟，所將降胡六百餘人叛走；", literal: "when the army had crossed to the end, more than six hundred surrendered Hu he led rebelled and fled;", idiomatic: "when the army had crossed to the end, more than six hundred surrendered Hu he led rebelled and fled;" },
  { zh: "衝將數百人追之，遇羌伏後，與戰而歿。", literal: "Chong led several hundred men in pursuit, met Qiang lying in ambush behind, fought, and died.", idiomatic: "Chong led several hundred men in pursuit, met Qiang lying in ambush behind, fought, and died." },
  { zh: "沖雖死，而前後多所斬獲，羌由是衰耗。", literal: "Though Chong died, before and after there were many beheadings and captures, and the Qiang thereby declined and were exhausted.", idiomatic: "Though Chong died, before and after there were many beheadings and captures, and the Qiang thereby declined and were exhausted." },
  { zh: "詔封沖子為義陽亭侯。", literal: "An edict enfeoffed Chong's son as Marquis of Yiyang village.", idiomatic: "An edict enfeoffed Chong's son as Marquis of Yiyang village." },
  { zh: "夏，四月，使匈奴中郎將馬寔擊南匈奴左部，破之。", literal: "In summer, the fourth month, sent Xiongnu Central Colonel Ma Shi to attack the Southern Xiongnu Left Division and defeated them.", idiomatic: "In summer, in the fourth month, Xiongnu Central Colonel Ma Shi was sent to attack the Southern Xiongnu Left Division and defeated them." },
  { zh: "於是胡、羌、烏桓悉詣寔降。", literal: "Thereupon the Hu, Qiang, and Wuhuan all came to Shi to surrender.", idiomatic: "Thereupon the Hu, Qiang, and Wuhuan all came to Shi to surrender." },
  { zh: "辛巳，立皇子炳為太子，改元，赦天下。", literal: "On xinsi day, established the imperial son Bing as heir apparent, changed the reign title, and amnestied the realm.", idiomatic: "On xinsi day, the imperial son Bing was established as heir apparent, the reign title was changed, and the realm was amnestied." },
  { zh: "太子居承光宮，帝使侍御史種暠監其家。", literal: "The heir apparent dwelt in Chengguang Palace; the emperor sent Attending Clerk Zhong Hao to supervise his household.", idiomatic: "The heir apparent dwelt in Chengguang Palace. The emperor sent Attending Clerk Zhong Hao to supervise his household." },
  { zh: "中常侍高梵從中單駕出迎太子，時太傅杜喬等疑不欲從而未決，暠乃手劍當車曰：「太子，國之儲副，人命所繫。", literal: "Regular Attendant Gao Fan came out from the inner palace with a single carriage to welcome the heir apparent. At the time Grand Tutor Du Qiao and others doubted and did not wish to follow yet had not decided. Hao then took sword in hand and blocked the carriage, saying: \"The heir apparent is the state's reserve deputy; human lives depend on him.", idiomatic: "Regular Attendant Gao Fan came out from the inner palace with a single carriage to welcome the heir apparent. At the time Grand Tutor Du Qiao and others doubted and did not wish to follow yet had not decided. Hao then took sword in hand and blocked the carriage, saying, \"The heir apparent is the state's reserve deputy. Human lives depend on him." },
  { zh: "今常侍來，無詔信，何以知非奸邪？", literal: "\" Now a regular attendant comes without edict or credential—how does one know he is not treacherous and wicked?", idiomatic: "\" Now a regular attendant comes without edict or credential—how does one know he is not treacherous and wicked?" },
  { zh: "今日有死而已！", literal: "\" Today there is only death!", idiomatic: "\" Today there is only death!" },
  { zh: "」梵辭屈，不敢對，馳還奏之。", literal: "\" Fan was defeated in words, dared not reply, and galloped back to report.", idiomatic: "\" Fan was defeated in words, dared not reply, and galloped back to report." },
  { zh: "詔報，太子乃得去。", literal: "An edict replied, and the heir apparent then was able to go.", idiomatic: "An edict replied, and the heir apparent then was able to go." },
  { zh: "喬退而歎息，愧暠臨事不惑；", literal: "Qiao withdrew and sighed, ashamed that Hao in the affair was not confused;", idiomatic: "Qiao withdrew and sighed, ashamed that Hao in the affair was not confused;" },
  { zh: "帝亦嘉其持重，稱善者良久。", literal: "the emperor also praised his steadiness and spoke approval for a long while.", idiomatic: "the emperor also praised his steadiness and spoke approval for a long while." },
  { zh: "揚、徐盜賊群起，盤互連歲。", literal: "In Yang and Xu bandits rose in groups, entwined year after year.", idiomatic: "In Yang and Xu bandits rose in groups, entwined year after year." },
  { zh: "秋，八月，九江范容、周生等寇掠城邑，屯據歷陽，為江、淮巨患；", literal: "In autumn, the eighth month, Fan Rong of Jiujiang, Zhou Sheng, and others raided and plundered cities and towns, encamped and held Liyang, and were a great calamity of the Jiang and Huai;", idiomatic: "In autumn, in the eighth month, Fan Rong of Jiujiang, Zhou Sheng, and others raided and plundered cities and towns, encamped and held Liyang, and were a great calamity of the Jiang and Huai;" },
  { zh: "遣御史中丞馮緄督州兵討之。", literal: "sent Imperial Secretary Feng Gun to supervise commandery troops in punishing them.", idiomatic: "Imperial Secretary Feng Gun was sent to supervise commandery troops in punishing them." },
  { zh: "庚午，帝崩於玉堂前殿。", literal: "On gengwu day the emperor died in the Jade Hall front palace.", idiomatic: "On gengwu day the emperor died in the Jade Hall front palace." },
  { zh: "太子即皇帝位，年二歲。", literal: "The heir apparent ascended the imperial throne; he was two years old.", idiomatic: "The heir apparent ascended the imperial throne. He was two years old." },
  { zh: "尊皇后曰皇太后。", literal: "The empress was honored as empress dowager.", idiomatic: "The empress was honored as empress dowager." },
  { zh: "太后臨朝。", literal: "The empress dowager held court.", idiomatic: "The empress dowager held court." },
  { zh: "丁丑，以太尉趙峻為太傅，大司農李固為太尉，參錄尚書事。", literal: "On dingchou day, made Grand Commandant Zhao Jun Grand Tutor and Grand Minister of Agriculture Li Gu Grand Commandant, with participation in recording Secretariat affairs.", idiomatic: "On dingchou day, Grand Commandant Zhao Jun was made Grand Tutor and Grand Minister of Agriculture Li Gu was made Grand Commandant, with participation in recording Secretariat affairs." },
  { zh: "九月，丙午，葬孝順皇帝於憲陵，廟曰敬宗。", literal: "In the ninth month, on bingwu day, buried Filial and Obedient Emperor at Xianling; his temple title is Jingzong.", idiomatic: "In the ninth month, on bingwu day, Filial and Obedient Emperor was buried at Xianling. His temple title is Jingzong." },
  { zh: "是日，京師及太原、雁門地震。", literal: "That day the capital together with Taiyuan and Yanmen had earthquakes.", idiomatic: "That day the capital, together with Taiyuan and Yanmen, had earthquakes." },
  { zh: "庚戌，詔舉賢良方正之士，策問之。", literal: "On gengxu day an edict ordered the recommendation of worthy and upright gentlemen for policy questioning.", idiomatic: "On gengxu day an edict ordered the recommendation of worthy and upright gentlemen for policy questioning." },
  { zh: "皇甫規對曰：「伏惟孝順皇帝初勤王政，紀綱四方，幾以獲安；", literal: "Huangfu Gui replied, saying: \"Your servant considers that Emperor Shun at first diligently governed royal affairs and ordered the four quarters, and almost attained peace;\"", idiomatic: "Huangfu Gui replied, saying, \"Your servant considers that Emperor Shun at first diligently governed royal affairs and ordered the four quarters, and almost attained peace;\"" },
  { zh: "後遭奸偽，威分近習，受賂賣爵，賓客交錯，天下擾擾，從亂如歸，官民並竭，上下窮虛。", literal: "\"afterward he met treacherous falsity, authority was divided among close attendants, bribes were taken and ranks sold, guests and clients crisscrossed, all under heaven was in turmoil, joining disorder as if returning home, officials and people were both exhausted, above and below were destitute and empty.\"", idiomatic: "\"afterward he met treacherous falsity. Authority was divided among close attendants, bribes were taken and ranks sold, guests and clients crisscrossed, all under heaven was in turmoil, and people joined disorder as if returning home. Officials and people were both exhausted, and above and below were destitute and empty.\"" },
  { zh: "陛下體兼乾坤，聰哲純茂，攝政之初，拔用忠貞，其餘維綱，多所改正，遠近翕然望見太平，而災異不息，寇賊縱橫，殆以奸臣權重之所致也。", literal: "\"Your Majesty's person embraces heaven and earth, pure in wisdom and virtue; at the start of regency you raised the loyal and straight, and of the rest of the sustaining cords many were corrected. Near and far alike looked to see great peace—yet prodigies do not cease and bandits roam at will, probably because treacherous ministers' power is heavy.\"", idiomatic: "\"Your Majesty's person embraces heaven and earth and is pure in wisdom and virtue. At the start of regency you raised the loyal and straight, and of the rest of the sustaining cords many were corrected. Near and far alike looked to see great peace—yet prodigies do not cease and bandits roam at will, probably because treacherous ministers' power is too heavy.\"" },
  { zh: "其常侍尤無狀者，宜亟黜遣，披掃凶黨，收入財賄，以塞痛怨，以答天誡。", literal: "\"Among the Regular Attendants those most lawless should be swiftly dismissed and expelled, the vicious faction swept away, their bribes and goods seized, to block bitter resentment and answer Heaven's warning.\"", idiomatic: "\"Among the Regular Attendants those most lawless should be swiftly dismissed and expelled, the vicious faction swept away, and their bribes and goods seized, to block bitter resentment and answer Heaven's warning.\"" },
  { zh: "大將軍冀、河南尹不疑，亦宜增修謙節，輔以儒術，省去游娛不急之務，割減廬第無益之飾。", literal: "\"Grand General Ji and Henan Intendant Bu Yi should also further cultivate modest conduct, be aided by Confucian learning, cut away idle amusements and unurgent affairs, and reduce useless ornament in their lodges and mansions.\"", idiomatic: "\"Grand General Ji and Henan Intendant Bu Yi should also further cultivate modest conduct, be aided by Confucian learning, cut away idle amusements and unurgent affairs, and reduce useless ornament in their lodges and mansions.\"" },
  { zh: "夫君者，舟也；", literal: "\"The ruler is a boat;\"", idiomatic: "\"The ruler is a boat;\"" },
  { zh: "民者，水也；", literal: "\"the people are water;\"", idiomatic: "\"the people are water;\"" },
  { zh: "群臣，乘舟者也；", literal: "\"ministers are those who ride the boat;\"", idiomatic: "\"ministers are those who ride the boat;\"" },
  { zh: "將軍兄弟，操楫者也。", literal: "\"the general's brothers hold the oars.\"", idiomatic: "\"the general's brothers hold the oars.\"" },
  { zh: "若能平志畢力，以度元元，所謂福也。", literal: "\"If they can level their wills and exhaust their strength to measure out the common folk, that is what is called blessing.\"", idiomatic: "\"If they can level their wills and exhaust their strength to measure out the common folk, that is what is called blessing.\"" },
  { zh: "如其怠弛，將淪波濤，可不慎乎！", literal: "\"If they are slack and lax, they will sink in the waves—can one not be cautious!\"", idiomatic: "\"If they are slack and lax, they will sink in the waves—can one not be cautious!\"" },
  { zh: "夫德不稱祿，猶鑿墉之趾以益其高，豈量力審功，安固之道哉！", literal: "\"When virtue does not match salary, it is like chiseling a wall's foot to raise its height—how is that measuring strength and examining achievement, the way to secure stability!\"", idiomatic: "\"When virtue does not match salary, it is like chiseling a wall's foot to raise its height—how is that measuring strength and examining achievement, the way to secure stability!\"" },
  { zh: "凡諸宿猾、酒徒、戲客，皆宜貶斥，以懲不軌。", literal: "\"All old rogues, wine companions, and play guests should be demoted and expelled to punish irregular conduct.\"", idiomatic: "\"All old rogues, wine companions, and play guests should be demoted and expelled to punish irregular conduct.\"" },
  { zh: "令冀等深思得賢之福，失人之累。", literal: "\"Let Ji and the others deeply think on the blessing of obtaining the worthy and the burden of losing men.\"", idiomatic: "\"Let Ji and the others deeply think on the blessing of obtaining the worthy and the burden of losing men.\"" },
  { zh: "」梁冀忿之，以規為下第，拜郎中；", literal: "\" Liang Ji was angry at this, ranked Gui in the lowest grade, and appointed him Palace Gentleman;", idiomatic: "\" Liang Ji was angry at this, ranked Gui in the lowest grade, and appointed him Palace Gentleman;" },
  { zh: "托疾，免歸，州郡承冀旨，幾陷死者再三，遂沉廢於家，積十餘年。", literal: "he pleaded illness and was dismissed to return home; commanderies and districts followed Ji's intent, and several times he nearly died in traps, until he sank into disuse at home for more than ten years.", idiomatic: "he pleaded illness and was dismissed to return home. Commanderies and districts followed Ji's intent, and several times he nearly died in traps, until he sank into disuse at home for more than ten years." },
  { zh: "揚州刺史尹耀、九江太守鄧顯討范容等於歷陽，敗歿。", literal: "Inspector of Yangzhou Yin Yao and Administrator of Jiujiang Deng Xian attacked Fan Rong and others at Liyang and were defeated and killed.", idiomatic: "Inspector of Yangzhou Yin Yao and Administrator of Jiujiang Deng Xian attacked Fan Rong and others at Liyang and were defeated and killed." },
  { zh: "冬，十月，日南蠻夷復反，攻燒縣邑。", literal: "In winter, the tenth month, the Man and Yi of Rinan again rebelled, attacking and burning counties and towns.", idiomatic: "In winter, in the tenth month, the Man and Yi of Rinan again rebelled, attacking and burning counties and towns." },
  { zh: "交趾刺史九江夏方招誘降之。", literal: "Inspector of Jiaozhi Xia Fang of Jiujiang induced and accepted their surrender.", idiomatic: "Inspector of Jiaozhi Xia Fang of Jiujiang induced and accepted their surrender." },
  { zh: "十一月，九江盜賊徐鳳、馬勉等攻燒城邑；", literal: "In the eleventh month, bandits of Jiujiang Xu Feng, Ma Mian, and others attacked and burned cities and towns;", idiomatic: "In the eleventh month, bandits of Jiujiang Xu Feng, Ma Mian, and others attacked and burned cities and towns;" },
  { zh: "鳳稱無上將軍，勉稱皇帝，築營於當塗山中，建年號，置百官。", literal: "Feng styled himself Supreme General, Mian styled himself Emperor, built camps in Dangtu mountain, established an era name, and installed the hundred offices.", idiomatic: "Feng styled himself Supreme General, Mian styled himself Emperor, built camps in Dangtu mountain, established an era name, and installed the hundred offices." },
  { zh: "十二月，九江賊黃虎等攻合肥。", literal: "In the twelfth month, the Jiujiang bandit Huang Hu and others attacked Hefei.", idiomatic: "In the twelfth month, the Jiujiang bandit Huang Hu and others attacked Hefei." },
  { zh: "是歲，群盜發憲陵。", literal: "That year a host of bandits broke into Xian Mausoleum.", idiomatic: "That year a host of bandits broke into Xian Mausoleum." },
  { zh: "漢孝皇帝", literal: "Han Filial Emperor", idiomatic: "Han Filial Emperor" },
  { zh: "春，正月，戊戌，帝崩於玉堂前殿。", literal: "In spring, the first month, on wuxu day, the Emperor died in the front hall of the Jade Hall.", idiomatic: "In spring, in the first month, on wuxu day, the Emperor died in the front hall of the Jade Hall." },
  { zh: "梁太后以揚、徐盜賊方盛，欲須所征諸王侯到乃發喪。", literal: "Empress Dowager Liang, because bandits in Yang and Xu were still strong, wished to wait until the summoned kings and marquises arrived before announcing the mourning.", idiomatic: "Empress Dowager Liang, because bandits in Yang and Xu were still strong, wished to wait until the summoned kings and marquises arrived before announcing the mourning." },
  { zh: "太尉李固曰：「帝雖幼少，猶天下之父。", literal: "Grand Commandant Li Gu said: \"Though the Emperor was young, he was still father to all under heaven.\"", idiomatic: "Grand Commandant Li Gu said, \"Though the Emperor was young, he was still father to all under heaven.\"" },
  { zh: "今日崩亡，人神感動，豈有人子反共掩匿乎！", literal: "\"Today he has died and collapsed—men and spirits are moved; how could any human child in turn together conceal it!\"", idiomatic: "\"Today he has died—men and spirits are moved. How could any human child in turn together conceal it!\"" },
  { zh: "昔秦皇沙丘之謀及近日北鄉之事，皆秘不發喪，此天下大忌，不可之甚者也！", literal: "\"Formerly the First Emperor of Qin's plot at Shaji and recently the affair at Beixiang—all kept the mourning secret and did not announce it. These are great taboos under heaven and must not be carried to extremes!\"", idiomatic: "\"Formerly the First Emperor of Qin's plot at Shaji and recently the affair at Beixiang—all kept the mourning secret and did not announce it. These are great taboos under heaven and must not be carried to extremes!\"" },
  { zh: "」太后從之，即暮發喪。", literal: "\" The Dowager followed this and that very evening announced the mourning.", idiomatic: "\" The Dowager followed this and that very evening announced the mourning." },
  { zh: "征清河王蒜及渤海孝王鴻之子纘皆至京師。", literal: "The summoned Prince Su of Qinghe and Zuan, son of Filial King Hong of Bohai, both reached the capital.", idiomatic: "The summoned Prince Su of Qinghe and Zuan, son of Filial King Hong of Bohai, both reached the capital." },
  { zh: "蒜父曰清河恭王延平；", literal: "Su's father was Respectful King Yanping of Qinghe;", idiomatic: "Su's father was Respectful King Yanping of Qinghe;" },
  { zh: "延平及鴻皆樂安夷王寵之子，千乘貞王伉之孫也。", literal: "Yanping and Hong were both sons of King Chong of Le'an, grandsons of Upright King Kang of Qiancheng.", idiomatic: "Yanping and Hong were both sons of King Chong of Le'an, grandsons of Upright King Kang of Qiancheng." },
  { zh: "清河王為人嚴重，動止有法度，公卿皆歸心焉。", literal: "The Prince of Qinghe was grave in person; his movements and stops had law and measure, and dukes and ministers all turned their hearts to him.", idiomatic: "The Prince of Qinghe was grave in person. His movements and stops had law and measure, and dukes and ministers all turned their hearts to him." },
  { zh: "李固謂大將軍冀曰：「今當立帝，宜擇長年，高明有德，任親政事者，願將軍審詳大計，察周、霍之立文、宣，戒鄧、閻之利幼弱！", literal: "Li Gu said to Grand General Ji: \"Now in establishing an emperor one should choose one mature in years, lofty and bright in virtue, able to handle close affairs of government. Your servant wishes the general to examine the great plan carefully, observe how Zhou and Huo established Wen and Xuan, and take warning from how Deng and Yan profited from installing the young and weak!\"", idiomatic: "Li Gu said to Grand General Ji, \"Now in establishing an emperor one should choose one mature in years, lofty and bright in virtue, and able to handle close affairs of government. Your servant wishes the general to examine the great plan carefully, observe how Zhou and Huo established Wen and Xuan, and take warning from how Deng and Yan profited from installing the young and weak!\"" },
  { zh: "」冀不從，與太后定策禁中。", literal: "\" Ji did not follow this but with the Dowager fixed the plan within the inner palace.", idiomatic: "\" Ji did not follow this but with the Dowager fixed the plan within the inner palace." },
  { zh: "丙辰，冀持節以王青蓋車迎纘入南宮。", literal: "On bingchen day Ji, bearing the staff of authority, welcomed Zuan into the Southern Palace in the king's green-canopied carriage.", idiomatic: "On bingchen day Ji, bearing the staff of authority, welcomed Zuan into the Southern Palace in the king's green-canopied carriage." },
  { zh: "丁巳，封為建平侯。", literal: "On dingsi day he was enfeoffed as Marquis of Jianping.", idiomatic: "On dingsi day he was enfeoffed as Marquis of Jianping." },
  { zh: "其日，即皇帝位，年八歲。", literal: "That same day he took the imperial throne; he was eight years old.", idiomatic: "That same day he took the imperial throne. He was eight years old." },
  { zh: "蒜罷歸國。", literal: "Su was dismissed and returned to his state.", idiomatic: "Su was dismissed and returned to his state." },
  { zh: "將卜山陵，李固曰：「今處處寇賊，軍興費廣，新創憲陵，賦發非一。", literal: "When they were about to divine the mountain tomb, Li Gu said: \"Now bandits are everywhere, military costs are vast, Xian Mausoleum was newly built, and levies are many.\"", idiomatic: "When they were about to divine the mountain tomb, Li Gu said, \"Now bandits are everywhere, military costs are vast, Xian Mausoleum was newly built, and levies are many.\"" },
  { zh: "帝尚幼小，可起陵於憲陵塋內，依康陵制度。", literal: "\"The Emperor is still young; his tomb may be raised within the precinct of Xian Mausoleum, following the institution of Kang Mausoleum.\"", idiomatic: "\"The Emperor is still young. His tomb may be raised within the precinct of Xian Mausoleum, following the institution of Kang Mausoleum.\"" },
  { zh: "」太后從之。", literal: "\" The Dowager followed this.", idiomatic: "\" The Dowager followed this." },
  { zh: "己未，葬孝沖皇帝於懷陵。", literal: "On jiwei day Filial Emperor Chong was buried at Huai Mausoleum.", idiomatic: "On jiwei day Filial Emperor Chong was buried at Huai Mausoleum." },
  { zh: "太后委政宰輔，李固所言，太后多從之，黃門宦官為惡者一皆斥遣，天下鹹望治平。", literal: "The Dowager entrusted government to the chief ministers; what Li Gu said the Dowager mostly followed, and wicked eunuchs of the Yellow Gates were all expelled. All under heaven looked to good order and peace.", idiomatic: "The Dowager entrusted government to the chief ministers. What Li Gu said the Dowager mostly followed, and wicked eunuchs of the Yellow Gates were all expelled. All under heaven looked to good order and peace." },
  { zh: "而梁冀深忌疾之。", literal: "Yet Liang Ji deeply hated and resented him.", idiomatic: "Yet Liang Ji deeply hated and resented him." },
  { zh: "初，順帝時所除官多不以次；", literal: "Initially, offices appointed in Emperor Shun's time were often not in proper order;", idiomatic: "Initially, offices appointed in Emperor Shun's time were often not in proper order;" },
  { zh: "及固在事，奏免百餘人。", literal: "when Gu was in office he memorialized to dismiss more than a hundred men.", idiomatic: "when Gu was in office he memorialized to dismiss more than a hundred men." },
  { zh: "此等既怨，又希望冀旨，遂共作飛章誣奏固曰：「太尉李固，因公假私，依正行邪，離間近戚，自隆支黨。", literal: "These men were already resentful and also hoped for Ji's intent; thereupon they jointly made a flying memorial falsely accusing Gu, saying: \"Grand Commandant Li Gu uses public office for private ends, relies on the upright to act crookedly, estranges close kin, and exalts his own faction.\"", idiomatic: "These men were already resentful and also hoped for Ji's intent. Thereupon they jointly made a flying memorial falsely accusing Gu, saying, \"Grand Commandant Li Gu uses public office for private ends, relies on the upright to act crookedly, estranges close kin, and exalts his own faction.\"" },
  { zh: "大行在殯，路人掩涕，固獨胡粉飾貌，搔頭弄姿，槃旋偃仰，從容治步，曾無慘怛傷悴之心。", literal: "\"The late sovereign lies in the coffin and travelers on the road cover their faces in tears, yet Gu alone powders his face and ornaments his looks, scratches his head and plays with his bearing, turns round reclining and rising, walks with easy composure—never a heart of grief and sorrow.\"", idiomatic: "\"The late sovereign lies in the coffin and travelers on the road cover their faces in tears, yet Gu alone powders his face and ornaments his looks, scratches his head and plays with his bearing, turns round reclining and rising, and walks with easy composure—never a heart of grief and sorrow.\"" },
  { zh: "山陵未成，違矯舊政，善則稱己，過則歸君；", literal: "\"The mountain tomb is not yet complete, yet he violates and bends old government—what is good he claims for himself, what is faulty he assigns to the ruler;\"", idiomatic: "\"The mountain tomb is not yet complete, yet he violates and bends old government—what is good he claims for himself, and what is faulty he assigns to the ruler;\"" },
  { zh: "斥逐近臣，不得侍送。", literal: "\"he expels and drives away close attendants so they cannot serve and escort.\"", idiomatic: "\"he expels and drives away close attendants so they cannot serve and escort.\"" },
  { zh: "作威作福，莫固之甚矣！", literal: "\"Making might and making blessing—none exceeds Gu in this!\"", idiomatic: "\"Making might and making blessing—none exceeds Gu in this!\"" },
  { zh: "夫子罪莫大於累父，臣惡莫深於毀君，固之過釁，事合誅辟。", literal: "\"The Master's saying: no crime is greater than bringing down one's father; no wickedness of a minister is deeper than destroying his ruler. Gu's excess fault and offense fit execution by law.\"", idiomatic: "\"The Master's saying: no crime is greater than bringing down one's father; no wickedness of a minister is deeper than destroying his ruler. Gu's excess fault and offense fit execution by law.\"" },
  { zh: "」書奏，冀以白太后，使下其書；", literal: "\" The memorial was submitted; Ji reported it to the Dowager and had the document sent down;", idiomatic: "\" The memorial was submitted. Ji reported it to the Dowager and had the document sent down;" },
  { zh: "太后不聽。", literal: "the Dowager would not listen.", idiomatic: "the Dowager would not listen." },
  { zh: "廣陵賊張嬰復聚眾數千人反，據廣陵。", literal: "The Guangling bandit Zhang Ying again gathered several thousand men in rebellion and held Guangling.", idiomatic: "The Guangling bandit Zhang Ying again gathered several thousand men in rebellion and held Guangling." },
  { zh: "二月，乙酉，赦天下。", literal: "In the second month, on yiyou day, amnesty was declared for all under heaven.", idiomatic: "In the second month, on yiyou day, amnesty was declared for all under heaven." },
  { zh: "西羌叛亂積年，費用八十餘億。", literal: "The Western Qiang rebellion had piled up for years; expenses exceeded eight billion.", idiomatic: "The Western Qiang rebellion had piled up for years. Expenses exceeded eight billion." },
  { zh: "諸將多斷盜牢稟，私自潤入，皆以珍寶貨賂左右。", literal: "The generals mostly intercepted and stole the garrison grain, privately enriching themselves, and all used gems and treasures to bribe those around the throne.", idiomatic: "The generals mostly intercepted and stole the garrison grain and privately enriched themselves, and all used gems and treasures to bribe those around the throne." },
  { zh: "上下放縱，不恤軍事，士卒不得其死者，白骨相望於野。", literal: "Above and below were lax and indulgent, uncaring of military affairs; soldiers did not obtain death in due course, and white bones looked at one another across the fields.", idiomatic: "Above and below were lax and indulgent and uncaring of military affairs. Soldiers did not obtain death in due course, and white bones looked at one another across the fields." },
  { zh: "左馮翊梁並以恩信招誘叛羌；", literal: "Liang Bing, Intendant of the Left of Fengyi, with grace and trust induced the rebellious Qiang;", idiomatic: "Liang Bing, Intendant of the Left of Fengyi, with grace and trust induced the rebellious Qiang;" },
  { zh: "離湳、狐奴等五萬餘戶皆詣並降，隴右復平。", literal: "more than fifty thousand households of Liqian, Hunu, and others all came to Bing and surrendered, and Longyou was again pacified.", idiomatic: "more than fifty thousand households of Liqian, Hunu, and others all came to Bing and surrendered, and Longyou was again pacified." },
  { zh: "太后以徐、揚盜賊益熾，博求將帥。", literal: "The Dowager, because bandits in Xu and Yang grew ever fiercer, broadly sought generals.", idiomatic: "The Dowager, because bandits in Xu and Yang grew ever fiercer, broadly sought generals." },
  { zh: "三公舉涿令北海滕撫有文武才；", literal: "The Three Excellencies recommended Magistrate of Zhuo Teng Fu of Beihai as having civil and military talent;", idiomatic: "The Three Excellencies recommended Magistrate of Zhuo Teng Fu of Beihai as having civil and military talent;" },
  { zh: "詔拜撫九江都尉，與中郎將趙序助馮緄，合州郡兵數萬人共討之。", literal: "an edict appointed Fu Colonel of Jiujiang, to assist Feng Gun together with Colonel of the Gentlemen Zhao Xu, combining commandery and district troops numbering tens of thousands to attack them jointly.", idiomatic: "an edict appointed Fu Colonel of Jiujiang to assist Feng Gun together with Colonel of the Gentlemen Zhao Xu, combining commandery and district troops numbering tens of thousands to attack them jointly." },
  { zh: "又廣開賞募，錢、邑各有差。", literal: "Rewards and bounties were also broadly opened, with money and fiefs each graded.", idiomatic: "Rewards and bounties were also broadly opened, with money and fiefs each graded." },
  { zh: "又議遣太尉李固，未及行。", literal: "They also deliberated sending Grand Commandant Li Gu, but before he could go.", idiomatic: "They also deliberated sending Grand Commandant Li Gu, but he had not yet departed." },
  { zh: "三月，撫等進擊眾賊，大破之，斬馬勉、范容、周生等千五百級。", literal: "In the third month, Fu and others advanced to attack the mass of bandits and routed them greatly, beheading Ma Mian, Fan Rong, Zhou Sheng, and others to the number of fifteen hundred.", idiomatic: "In the third month, Fu and others advanced to attack the mass of bandits and routed them greatly, beheading Ma Mian, Fan Rong, Zhou Sheng, and others to the number of fifteen hundred." },
  { zh: "徐鳳以餘眾燒東城縣。", literal: "Xu Feng with the remnant host burned Dongcheng county.", idiomatic: "Xu Feng with the remnant host burned Dongcheng county." },
  { zh: "夏，五月，下邳人謝安應募，率其宗親設伏擊鳳，斬之。", literal: "In summer, the fifth month, Xie An of Xiapi answered the bounty, led his clan and kin to set an ambush and strike Feng, and beheaded him.", idiomatic: "In summer, in the fifth month, Xie An of Xiapi answered the bounty, led his clan and kin to set an ambush and strike Feng, and beheaded him." },
  { zh: "封安為平鄉侯。", literal: "An was enfeoffed as Marquis of Pingxiang.", idiomatic: "An was enfeoffed as Marquis of Pingxiang." },
  { zh: "拜滕撫中郎將，督揚、徐二州事。", literal: "Teng Fu was appointed Colonel of the Gentlemen and supervised the affairs of the two provinces Yang and Xu.", idiomatic: "Teng Fu was appointed Colonel of the Gentlemen and supervised the affairs of the two provinces Yang and Xu." },
  { zh: "丙辰，詔曰：「孝殤皇帝即位逾年，君臣禮成。", literal: "On bingchen day an edict said: \"Filial Emperor Shang had been on the throne more than a year; ruler and ministers' ritual was complete.\"", idiomatic: "On bingchen day an edict said, \"Filial Emperor Shang had been on the throne more than a year; ruler and ministers' ritual was complete.\"" },
  { zh: "孝安皇帝承襲統業，而前世遂令恭陵在康陵之上，先後相逾，失其次序。", literal: "\"Filial Emperor An inherited the unified enterprise, yet the previous age had placed Gong Mausoleum above Kang Mausoleum—the former and latter overstepped one another and lost proper order.\"", idiomatic: "\"Filial Emperor An inherited the unified enterprise, yet the previous age had placed Gong Mausoleum above Kang Mausoleum—the former and latter overstepped one another and lost proper order.\"" },
  { zh: "今其正之！", literal: "\"Now rectify this!\"", idiomatic: "\"Now rectify this!\"" },
  { zh: "六月，鮮卑寇代郡。", literal: "In the sixth month the Xianbei raided Dai commandery.", idiomatic: "In the sixth month the Xianbei raided Dai commandery." },
  { zh: "秋，廬江盜賊攻尋陽，又攻盱台。", literal: "In autumn, bandits of Lujiang attacked Xunyang and also attacked Yutai.", idiomatic: "In autumn, bandits of Lujiang attacked Xunyang and also attacked Yutai." },
  { zh: "滕撫遣司馬王章擊破之。", literal: "Teng Fu sent Major Wang Zhang to attack and defeat them.", idiomatic: "Teng Fu sent Major Wang Zhang to attack and defeat them." },
  { zh: "九月，庚戌，太傅趙峻薨。", literal: "In the ninth month, on gengxu day, Grand Tutor Zhao Jun died.", idiomatic: "In the ninth month, on gengxu day, Grand Tutor Zhao Jun died." },
  { zh: "滕撫進擊張嬰；", literal: "Teng Fu advanced to attack Zhang Ying;", idiomatic: "Teng Fu advanced to attack Zhang Ying;" },
  { zh: "冬，十一月，丙午，破嬰，斬獲千餘人。", literal: "in winter, the eleventh month, on bingwu day, he defeated Ying and beheaded and captured more than a thousand men.", idiomatic: "in winter, in the eleventh month, on bingwu day, he defeated Ying and beheaded and captured more than a thousand men." },
  { zh: "丁未，中郎將趙序坐畏懦、詐增首級，棄市。", literal: "On dingwei day Colonel of the Gentlemen Zhao Xu, charged with cowardice and falsely inflating heads taken, was exposed in the market.", idiomatic: "On dingwei day Colonel of the Gentlemen Zhao Xu, charged with cowardice and falsely inflating heads taken, was exposed in the market." },
  { zh: "歷陽賊華孟自稱黑帝，攻殺九江太守楊岑。", literal: "The Liyang bandit Hua Meng styled himself Black Emperor and attacked and killed Administrator of Jiujiang Yang Cen.", idiomatic: "The Liyang bandit Hua Meng styled himself Black Emperor and attacked and killed Administrator of Jiujiang Yang Cen." },
  { zh: "滕撫進擊，破之，斬孟等三千八百級，虜獲七百餘人。", literal: "Teng Fu advanced to attack, defeated them, and beheaded Meng and others to the number of thirty-eight hundred, capturing more than seven hundred.", idiomatic: "Teng Fu advanced to attack and defeated them, beheading Meng and others to the number of thirty-eight hundred and capturing more than seven hundred." },
  { zh: "於是東南悉平，振旅而還。", literal: "Thereupon the southeast was entirely pacified; he shook out the troops and returned.", idiomatic: "Thereupon the southeast was entirely pacified. He shook out the troops and returned." },
  { zh: "以撫為左馮翊。", literal: "Fu was made Intendant of the Left of Fengyi.", idiomatic: "Fu was made Intendant of the Left of Fengyi." },
  { zh: "永昌太守劉君世，鑄黃金為文蛇，以獻大將軍冀；", literal: "Administrator of Yongchang Liu Junshi cast gold into an inscribed serpent and presented it to Grand General Ji;", idiomatic: "Administrator of Yongchang Liu Junshi cast gold into an inscribed serpent and presented it to Grand General Ji;" },
  { zh: "益州刺史種暠糾發逮捕，馳傳上言。", literal: "Inspector of Yizhou Zhong Hao investigated, exposed, and arrested him, and by rapid post memorialized above.", idiomatic: "Inspector of Yizhou Zhong Hao investigated, exposed, and arrested him, and by rapid post memorialized above." },
  { zh: "冀由是恨暠。", literal: "Ji thereby hated Hao.", idiomatic: "Ji thereby hated Hao." },
  { zh: "會巴郡人服直聚黨數百人，自稱天王，暠與太守應承討捕，不克，吏民多被傷害；", literal: "It happened that Fu Zhi of Ba commandery gathered a party of several hundred men and styled himself Heavenly King. Hao together with the Administrator Ying Cheng pursued and captured them but did not overcome them; officials and people suffered many injuries;", idiomatic: "It happened that Fu Zhi of Ba commandery gathered a party of several hundred men and styled himself Heavenly King. Hao together with the Administrator Ying Cheng pursued and captured them but did not overcome them, and officials and people suffered many injuries;" },
  { zh: "冀因此陷之，傳逮暠、承。", literal: "Ji used this to trap them and by post summoned Hao and Cheng for arrest.", idiomatic: "Ji used this to trap them and by post summoned Hao and Cheng for arrest." },
  { zh: "李固上疏曰：「臣伏聞討捕所傷，本非暠、承之意，實由縣吏懼法畏罪，迫逐深苦，致此不詳。", literal: "Li Gu submitted a memorial, saying: \"Your servant has heard that the injuries in the pursuit and capture were not originally Hao's and Cheng's intent; truly it was because district clerks feared the law and dreaded punishment, pressing the pursuit with deep harshness and bringing this misfortune.\"", idiomatic: "Li Gu submitted a memorial, saying, \"Your servant has heard that the injuries in the pursuit and capture were not originally Hao's and Cheng's intent. Truly it was because district clerks feared the law and dreaded punishment, pressed the pursuit with deep harshness, and brought this misfortune.\"" },
  { zh: "比盜賊群起，處處未絕。", literal: "\"Just now bandits rise in masses and are not yet ended anywhere.\"", idiomatic: "\"Just now bandits rise in masses and are not yet ended anywhere.\"" },
  { zh: "暠、承以首舉大奸而相隨受罪，臣恐沮傷州縣糾發之意，更共飾匿，莫復盡心！", literal: "\"Hao and Cheng, for having been first to expose a great villain, follow into punishment—your servant fears this will discourage the intent of provinces and districts to investigate and expose, and they will again together cover and conceal, no longer doing their utmost!\"", idiomatic: "\"Hao and Cheng, for having been first to expose a great villain, follow into punishment—your servant fears this will discourage the intent of provinces and districts to investigate and expose, and they will again together cover and conceal, no longer doing their utmost!\"" },
  { zh: "」太后省奏，乃赦暠、承罪，免官而已。", literal: "\" The Dowager examined the memorial and thereupon pardoned Hao's and Cheng's crimes, dismissing them from office only.", idiomatic: "\" The Dowager examined the memorial and thereupon pardoned Hao's and Cheng's crimes, dismissing them from office only." },
  { zh: "金蛇輸司農，冀從大司農杜喬借觀之，喬不肯與；", literal: "The golden serpent was delivered to the Minister of Agriculture; Ji asked to borrow it for viewing from Grand Minister of Agriculture Du Qiao, and Qiao would not give it;", idiomatic: "The golden serpent was delivered to the Minister of Agriculture. Ji asked to borrow it for viewing from Grand Minister of Agriculture Du Qiao, and Qiao would not give it;" },
  { zh: "冀小女死，令公卿會喪，喬獨不往，冀由是銜之。", literal: "Ji's young daughter died; he ordered the dukes and ministers to attend the mourning, but Qiao alone did not go—Ji thereby harbored resentment against him.", idiomatic: "Ji's young daughter died. He ordered the dukes and ministers to attend the mourning, but Qiao alone did not go. Ji thereby harbored resentment against him." },
  { zh: "category:資治通鑑", literal: "—", idiomatic: "—" }
];
